window.AponarN3Deep = {"lang": "fil", "map": {"কোনো কাজ বা পরিবর্তনের “শুরুর সীমানা” দেখায়। 始める-এর আগে যে verb থাকে, সেটিই শুরু হওয়া কাজ; তাই 読み始める মানে “পড়া নামের কাজ শুরু করা”।": "Ipinapakita nito ang \"hangganan ng pagsisimula\" ng isang aksyon o pagbabago. Ang verb bago ang 始める ang siyang aksyong nagsisimula; kaya ang 読み始める ay nangangahulugang \"simulan ang aksyong pagbabasa\".", "ইচ্ছাকৃত কাজ ও ধীরে শুরু হওয়া প্রাকৃতিক ঘটনা—দুই ক্ষেত্রেই চলে। তবে 結婚する・死ぬ-এর মতো এক মুহূর্তে সম্পূর্ণ হওয়া verb-এর সঙ্গে সাধারণত অস্বাভাবিক শোনায়।": "Gumagana ito kapwa sa sinasadyang aksyon at sa mga natural na pangyayaring unti-unting nagsisimula. Ngunit sa mga verb na natatapos sa isang iglap tulad ng 結婚する・死ぬ, karaniwang hindi ito natural pakinggan.", "～出す-এ হঠাৎ/অপ্রত্যাশিত শুরুর ঝাঁকুনি আছে; ～始める নিরপেক্ষ। ～続ける শুরু নয়, শুরু হওয়ার পর একই কাজ চলতে থাকা বোঝায়।": "Ang ～出す ay may biglaan/hindi inaasahang simula; ang ～始める ay neutral. Ang ～続ける ay hindi simula, kundi nangangahulugang nagpapatuloy ang parehong aksyon matapos itong magsimula.", "মোবাইলের START বোতাম চাপার ছবি মনে করো: ます বাদ → কাজের নাম → 始める। 読みます → 読み始める।": "Isipin ang larawan ng pagpindot sa START button ng cellphone: alisin ang ます → pangalan ng aksyon → 始める. 読みます → 読み始める.", "“আমি গত মাস থেকে N3 পড়া শুরু করেছি”—নিজের তথ্য দিয়ে একটি বাক্য বলো।": "\"Nagsimula akong mag-aral ng N3 noong nakaraang buwan\" — bumuo ng isang pangungusap gamit ang sarili mong impormasyon.", "অন্য কেউ যে নির্দেশ দিয়েছে, সেটিকে হুবহু quote না করে “কী করতে বলেছে” হিসেবে জানায়। ように-এর আগের অংশ হলো নির্দেশের content, に-marked ব্যক্তি হলো নির্দেশদাতা।": "Ipinapahayag nito ang isang utos na ibinigay ng iba, hindi bilang eksaktong quote kundi bilang \"kung ano ang sinabing gawin\". Ang bahaging bago ang ように ang content ng utos, at ang taong may に ang nagbigay ng utos.", "辞書形 হলে করতে বলা, ない形 হলে না করতে বলা। নিজের ইচ্ছা নয়; বাইরে থেকে পাওয়া নির্দেশ, অনুরোধ বা সতর্কতা বোঝায়।": "Kung 辞書形, ibig sabihin ay sinabihang gawin; kung ない形, sinabihang huwag gawin. Hindi ito sariling kagustuhan; ipinapakita nito ang utos, kahilingan, o babala na nagmula sa labas.", "「早く来て」と言われた হলো সরাসরি quote; 早く来るように言われた হলো একই কথার indirect report। সাধারণ বক্তব্যের ということ-এর সঙ্গে গুলিও না।": "Ang 「早く来て」と言われた ay direktang quote; ang 早く来るように言われた ay indirect report ng parehong sinabi. Huwag itong ipagkamali sa ということ na ginagamit sa karaniwang pahayag.", "先生 → ように → 私—একটি তীরের ছবি: শিক্ষকের কথা ように দিয়ে তোমার দিকে এসেছে।": "先生 → ように → 私 — isang larawan ng palaso: ang sinabi ng guro ay dumating sa iyo sa pamamagitan ng ように.", "স্কুলে শিক্ষক তোমাকে যে একটি কাজ করতে বলেছেন, ように言われました দিয়ে বলো।": "Sabihin ang isang gawaing ipinagawa sa iyo ng guro sa paaralan, gamit ang ように言われました.", "একটি পুরো বাক্যকে “একটি তথ্য/ঘটনা” নামের noun-box-এ ঢোকায়। তাই বাক্যটির পরে を知る・が分かる・は大切だ ইত্যাদি বসতে পারে।": "Inilalagay nito ang isang buong pangungusap sa isang noun-box na tinatawag na \"isang impormasyon/pangyayari\". Kaya pagkatapos ng pangungusap ay maaaring ilagay ang を知る・が分かる・は大切だ at iba pa.", "কেবল অনুবাদে “যে” দেখলেই নয়—পরের অংশে তথ্যটিকে noun হিসেবে ধরার প্রয়োজন আছে কি না দেখো। N/なA-এর present affirmative-এ だということ হয়।": "Hindi lang dahil nakita mo ang \"na\" sa salin — tingnan kung kailangan bang tratuhin bilang noun ang impormasyon sa susunod na bahagi. Sa present affirmative ng N/なA, nagiging だということ ito.", "～ということです শোনা তথ্য জানাতেও ব্যবহৃত হয়; ～ということ শুধু nominalizer হতে পারে। ～の／こと-ও noun বানায়, কিন্তু ということ-এ “এই মর্মের তথ্য” ভাব স্পষ্ট।": "Ginagamit din ang ～ということです sa pag-uulat ng narinig na impormasyon; ang ～ということ ay maaari ring simpleng nominalizer lang. Ang ～の／こと ay gumagawa rin ng noun, ngunit sa ということ ay malinaw ang pakiramdam na \"impormasyong may ganitong nilalaman\".", "ということ-কে “তথ্যের বাক্স” ভাবো: পুরো sentence ঢুকল, বাইরে একটি noun বের হলো।": "Isipin ang ということ bilang \"kahon ng impormasyon\": pumasok ang buong sentence, at lumabas ang isang noun.", "“আগামীকাল পরীক্ষা নেই—এই কথা জানতাম না” ということを知らなかった দিয়ে বলো।": "\"Hindi ko alam na walang pagsusulit bukas\" — sabihin ito gamit ang ということを知らなかった.", "দেখা তথ্য বা নিজের বিচার থেকে ভবিষ্যৎ/অজানা বিষয়ে সম্ভাব্য সিদ্ধান্ত জানায়: “সম্ভবত এমন হবে—এটাই আমার ধারণা।”": "Mula sa nakitang impormasyon o sariling paghatol, ipinapahayag nito ang posibleng konklusyon tungkol sa hinaharap/hindi pa alam na bagay: \"Malamang ganito ang mangyayari — iyan ang palagay ko.\"", "だろう বক্তব্যকে অনুমান বানায়, と思う সেটিকে ব্যক্তিগত মত হিসেবে নরম করে। দৃঢ় প্রমাণভিত্তিক はず বা に違いない-এর চেয়ে অনিশ্চয়তা বেশি।": "Ginagawa ng だろう na hula ang pahayag, at pinapalambot ito ng と思う bilang personal na opinyon. Mas hindi ito tiyak kaysa sa はず o に違いない na batay sa matibay na ebidensya.", "～かと思います আরও ভদ্র ও নরম; ～に違いない অনেক দৃঢ়; ～そうだ যদি চেহারা দেখে তাৎক্ষণিক অনুমান হয়।": "Ang ～かと思います ay mas magalang at mas malambot; ang ～に違いない ay mas matibay; ang ～そうだ ay kung agarang hula batay sa nakitang anyo.", "মাথার ভেতর মেঘ: だろう = “হয়তো”, 思う = “আমি ভাবি”—দুইটি একসাথে হলে নম্র অনুমান।": "Ulap sa loob ng ulo: だろう = \"siguro/baka\", 思う = \"sa tingin ko\" — kapag pinagsama ang dalawa, nagiging magalang na hula.", "আগামীকালের আবহাওয়া নিয়ে だろうと思います ব্যবহার করে একটি অনুমান বলো।": "Gumawa ng isang hula tungkol sa panahon bukas gamit ang だろうと思います.", "চোখে দেখা লক্ষণ থেকে কোনো কাজ “হবে বলে মনে হচ্ছে না” বোঝায়। এটি negative appearance; বাস্তব সত্য বা শোনা খবর নয়।": "Mula sa mga palatandaang nakikita, ipinapakita nito na \"mukhang hindi mangyayari\" ang isang aksyon. Ito ay negative appearance; hindi ito aktuwal na katotohanan o narinig na balita.", "Vない-এর শেষ い ফেলে なさそう: 行かない→行かなさそう。 いい-এর negative হলো よくない→よくなさそう; ない নিজে adjective হলে なさそう হয়।": "Alisin ang huling い ng Vない at idagdag ang なさそう: 行かない→行かなさそう. Ang negative ng いい ay よくない→よくなさそう; kung ang ない mismo ang adjective, nagiging なさそう.", "降りそう = দেখে মনে হচ্ছে পড়বে; 降らなさそう = মনে হচ্ছে পড়বে না; 降るそうだ = শুনেছি পড়বে। Form বদলালে source বদলে যায়।": "降りそう = sa tingin, batay sa nakikita, ay uulan; 降らなさそう = mukhang hindi uulan; 降るそうだ = narinig kong uulan. Kapag nagbago ang form, nagbabago rin ang source.", "ない-এর い দরজায় রেখে দাও, তারপর さそう ঢোকাও: 行かな＋さそう।": "Iwan ang い ng ない sa may pinto, pagkatapos ay ipasok ang さそう: 行かな＋さそう.", "খাবারের ছবি দেখে “এটা ঝাল হবে বলে মনে হচ্ছে না” なさそう দিয়ে বলো।": "Tumingin sa larawan ng pagkain at sabihin ang \"mukhang hindi ito maanghang\" gamit ang なさそう.", "A কাজ করার সঙ্গে সঙ্গে B-তে নতুন কিছু দেখা, বোঝা বা আবিষ্কার হলো। A হলো discovery-র দরজা; B সাধারণত past state/event।": "Kasabay ng paggawa ng A, may bagong nakita, naunawaan, o natuklasan sa B. Ang A ang pinto ng discovery; ang B ay karaniwang past state/event.", "A-এর পরে নিজের ইচ্ছামতো পরিকল্পিত কাজ বসানো যায় না। 開けると、雪が降っていた স্বাভাবিক; 開けると、買い物に行った অস্বাভাবিক, কারণ দ্বিতীয়টি নিজের সিদ্ধান্ত।": "Pagkatapos ng A, hindi maaaring ilagay ang isang planadong aksyon ayon sa sariling kagustuhan. Natural ang 開けると、雪が降っていた; hindi natural ang 開けると、買い物に行った, dahil ang pangalawa ay sariling desisyon.", "～たとたん-এ আকস্মিক ঘটনার shock; ～と、～た-তে “করতেই দেখলাম/জানলাম” discovery। ～たら-তে শর্ত বা আবিষ্কার দুটোই হতে পারে।": "Sa ～たとたん ay may shock ng biglaang pangyayari; sa ～と、～た ay discovery na \"pagkagawa ko, nakita/nalaman ko\". Sa ～たら ay maaaring kondisyon o discovery.", "দরজা খোলার ছবি: 開けると… ক্যামেরার সামনে নতুন দৃশ্য দেখা গেল—তাই পরের অংশ past।": "Larawan ng pagbubukas ng pinto: 開けると… isang bagong tanawin ang nakita sa harap ng camera — kaya past ang kasunod na bahagi.", "“স্টেশনে পৌঁছে দেখলাম ট্রেন চলে গেছে”—discovery pattern দিয়ে বলো।": "\"Pagdating ko sa istasyon, nakita kong umalis na ang tren\" — sabihin ito gamit ang discovery pattern.", "কোনো অবস্থা সাধারণ সীমা ছাড়িয়ে কতটা তীব্র, তা একটি ফল/অসম্ভব অবস্থার মাধ্যমে মাপে: “এত… যে…”।": "Sinusukat nito kung gaano katindi ang isang kalagayan na lumampas sa karaniwang hangganan, sa pamamagitan ng isang resulta/imposibleng kalagayan: \"sobrang… na…\".", "ほど-এর আগের clause হলো মাত্রার মাপকাঠি; পরে মূল অবস্থা। বাস্তব সংখ্যা নয়, অনুভূতির scale। Positive ও negative—দুটিতেই আসতে পারে।": "Ang clause bago ang ほど ang panukat ng antas; pagkatapos nito ang pangunahing kalagayan. Hindi ito aktuwal na numero, kundi scale ng pakiramdam. Maaari itong dumating sa positive at negative.", "～くらい-ও মাত্রা দেয় এবং কথ্যতর; ほど তুলনা/মাত্রায় একটু নিরপেক্ষ। ～ほど…ない আলাদা comparison structure।": "Ang ～くらい ay nagbibigay din ng antas at mas kolokyal; ang ほど ay medyo neutral sa paghahambing/antas. Ang ～ほど…ない ay ibang comparison structure.", "থার্মোমিটারের লাল দাগ সীমা ছাড়িয়েছে—যে ফল দেখে মাত্রা বোঝা যায়, সেই ফলের আগে ほど।": "Lumampas na sa hangganan ang pulang guhit ng thermometer — ang ほど ay inilalagay bago ang resultang nagpapakita ng antas.", "আজকের ক্লান্তি “দাঁড়াতে পারছি না এত…” এই কাঠামোয় বলো।": "Sabihin ang pagod mo ngayon sa istrukturang ito: \"sobrang pagod na hindi ako makatayo…\".", "সময়রেখায় “এখন” থেকে সামনে চলা কাজ বা পরিবর্তন দেখায়। いく এখানে শুধু শারীরিকভাবে যাওয়া নয়; ভবিষ্যতের দিকে এগোনোর arrow।": "Ipinapakita nito ang aksyon o pagbabagong umuusad pasulong mula sa \"ngayon\" sa timeline. Ang いく dito ay hindi lang pisikal na pagpunta; ito ay arrow na umuusad patungo sa hinaharap.", "দীর্ঘমেয়াদি পরিকল্পনা, সামাজিক পরিবর্তন, অভ্যাস চালিয়ে যাওয়া—এসব ক্ষেত্রে স্বাভাবিক। চলার দিক বক্তার বর্তমান সময়/স্থান থেকে দূরে।": "Natural ito sa pangmatagalang plano, pagbabagong panlipunan, pagpapatuloy ng nakagawian, at iba pa. Ang direksyon ng pag-usad ay palayo sa kasalukuyang oras/lugar ng nagsasalita.", "～てくる = অতীত থেকে এখন পর্যন্ত পরিবর্তন বা দূর থেকে কাছে; ～ていく = এখন থেকে ভবিষ্যৎ বা কাছ থেকে দূরে।": "～てくる = pagbabago mula nakaraan hanggang ngayon, o mula malayo patungo sa malapit; ～ていく = mula ngayon patungo sa hinaharap, o mula malapit patungo sa malayo.", "NOW |——→ FUTURE; arrow-এর মাথায় いく লিখে রাখো।": "NOW |——→ FUTURE; isulat ang いく sa dulo ng arrow.", "“এখন থেকে প্রতিদিন জাপানি পড়তে থাকব” ～ていきます দিয়ে বলো।": "\"Mula ngayon, patuloy akong mag-aaral ng Japanese araw-araw\" — sabihin ito gamit ang ～ていきます.", "একই কাজ থামানো ছাড়া বা নিয়মিতভাবে চালিয়ে যাওয়ার continuity দেখায়। আগে কাজ শুরু হয়েছে—এখন তার রেখা লম্বা হচ্ছে।": "Ipinapakita nito ang continuity ng pagpapatuloy ng parehong aksyon nang hindi tumitigil o nang regular. Nagsimula na ang aksyon noon — ngayon ay humahaba ang linya nito.", "সময় ধরে চলতে পারে এমন durative verb-এর সঙ্গে ভালো চলে। একবারেই শেষ হওয়া瞬間動詞-এর সঙ্গে বিশেষ context ছাড়া চলে না।": "Mahusay itong gumagana sa mga durative verb na maaaring magpatuloy sa paglipas ng oras. Sa mga verb na natatapos sa isang iglap (瞬間動詞), hindi ito gumagana nang walang espesyal na context.", "～ている বর্তমান চলমান অবস্থা দেখায়; ～続ける “থামিনি/চালিয়ে গেছি” জোর দেয়। ～ていく ভবিষ্যৎ দিকও যোগ করে।": "Ipinapakita ng ～ている ang kasalukuyang nagpapatuloy na kalagayan; binibigyang-diin ng ～続ける ang \"hindi tumigil/nagpatuloy\". Nagdaragdag din ang ～ていく ng direksyon patungo sa hinaharap.", "ます কেটে verb-কে একটি লম্বা রেললাইনে বসাও: 勉強し＋続ける।": "Alisin ang ます at ilagay ang verb sa isang mahabang riles ng tren: 勉強し＋続ける.", "তুমি কত মাস ধরে কাজ/পড়াশোনা চালিয়ে যাচ্ছ—続けています দিয়ে বলো।": "Sabihin kung ilang buwan mo nang ipinagpapatuloy ang iyong trabaho/pag-aaral, gamit ang 続けています.", "শ্রোতার বলা তথ্য বা ধরে নেওয়া পরিস্থিতিকে topic বানিয়ে তার ভিত্তিতে পরামর্শ, প্রস্তাব বা সহায়তা দেয়।": "Ginagawa nitong topic ang impormasyong sinabi ng kausap o ang ipinapalagay na sitwasyon, at batay doon ay nagbibigay ng payo, mungkahi, o tulong.", "AならB-তে B সাধারণত বক্তার judgement। N ও なA-এর だ বাদ যায়: 学生なら、静かなら।": "Sa AならB, ang B ay karaniwang judgement ng nagsasalita. Nawawala ang だ ng N at なA: 学生なら、静かなら.", "～たら সাধারণ “যদি/যখন”; ～なら “যেহেতু তুমি A বলছ/যদি A-ই হয়”। ～と automatic result-এ বেশি, advice-এ নয়।": "Ang ～たら ay karaniwang \"kung/kapag\"; ang ～なら ay \"yamang sinasabi mong A / kung A nga\". Ang ～と ay mas para sa automatic result, hindi para sa advice.", "বন্ধু বলল “新宿へ行く”; তুমি তার কথাটি তুলে নিলে—行くなら、この電車。": "Sinabi ng kaibigan mo na \"新宿へ行く\"; kinuha mo ang sinabi niya — 行くなら、この電車.", "এক বন্ধু সস্তা রেস্টুরেন্ট খুঁজছে—なら দিয়ে পরামর্শ দাও।": "Isang kaibigan ang naghahanap ng murang restaurant — bigyan siya ng payo gamit ang なら.", "という／と-এর কথ্য short form। নাম ব্যাখ্যা, উদ্ধৃতি, শোনা কথা বা topic—কথোপকথনে দ্রুত সংযোগ করে।": "Maikling kolokyal na anyo ng という／と. Mabilis nitong iniuugnay ang paliwanag ng pangalan, quotation, narinig na balita, o topic sa usapan.", "বন্ধু, পরিবার ও casual speech-এ স্বাভাবিক। আবেদনপত্র, রিপোর্ট, শিক্ষককে formal explanation-এ という／と ব্যবহার নিরাপদ।": "Natural ito sa mga kaibigan, pamilya, at casual speech. Sa aplikasyon, ulat, o formal na paliwanag sa guro, mas ligtas gamitin ang という／と.", "Nって人 = Nという人; 来ないって言った = 来ないと言った। Rule 38-এর Nって হলো は-এর casual topic—sentence position দেখে কাজ বুঝবে।": "Nって人 = Nという人; 来ないって言った = 来ないと言った. Ang Nって sa Rule 38 ay casual topic ng は — tingnan ang posisyon sa pangungusap upang maunawaan ang gamit.", "って হলো কথার zip-file: という লম্বা form ছোট হয়ে って হয়েছে।": "Ang って ay parang zip-file ng pananalita: ang mahabang anyong という ay umikli at naging って.", "“JLPT বলতে কী?” এবং “শুনেছি কাল ছুটি”—って দিয়ে দুই রকম বাক্য বলো।": "\"Ano ang ibig sabihin ng JLPT?\" at \"Narinig kong walang pasok bukas\" — sabihin ang dalawang uri ng pangungusap gamit ang って.", "অন্যের অনুমতি/সহযোগিতা পেয়ে বক্তা নিজে কিছু করার সুযোগ পেয়েছে—এই উপকারের দৃষ্টিভঙ্গি দেখায়।": "Ipinapakita nito ang pananaw ng benepisyo: nakakuha ang nagsasalita ng pagkakataong gumawa ng isang bagay dahil sa pahintulot/tulong ng iba.", "যিনি অনুমতি দিয়েছেন তাঁকে に দিয়ে চিহ্নিত করা যায়। もらう-তে অনুমতি পাওয়া ও কৃতজ্ঞতার অনুভূতি আছে; শুধু নিজের সিদ্ধান্ত নয়।": "Maaaring markahan ng に ang taong nagbigay ng pahintulot. Sa もらう ay may pakiramdam ng pagtanggap ng pahintulot at pasasalamat; hindi ito sariling desisyon lamang.", "～させていただく আরও বিনয়ী ও formal; ～てもらう-তে অন্য ব্যক্তি সরাসরি কাজটি করে দেয়, কিন্তু させてもらう-তে কাজটি বক্তাই করে।": "Ang ～させていただく ay mas magalang at formal; sa ～てもらう, ang ibang tao mismo ang gumagawa ng aksyon, ngunit sa させてもらう, ang nagsasalita ang gumagawa ng aksyon.", "Causative させる দরজা খুলল, もらう সেই অনুমতি “পাওয়া”—তারপর আমি কাজ করি।": "Binuksan ng causative させる ang pinto, at ang もらう ang \"pagtanggap\" ng pahintulot na iyon — pagkatapos, ako ang gagawa ng aksyon.", "ম্যানেজারের অনুমতিতে আগে বাড়ি ফিরেছ—させてもらいました দিয়ে বলো।": "Umuwi ka nang maaga nang may pahintulot ng manager — sabihin ito gamit ang させてもらいました.", "কেউ আমাকে জোর করে কাজ করিয়েছে—causative + passive একসঙ্গে। Subject হলো বাধ্য হওয়া ব্যক্তি, に-marked ব্যক্তি বাধ্যকারী।": "May pumilit sa akin na gawin ang isang bagay — causative + passive nang magkasama. Ang subject ay ang taong napilitan, at ang taong may に ang pumilit.", "সাধারণত অনিচ্ছা, কষ্ট বা অসন্তোষ থাকে। Group 1-এ 行く→行かせられる/কথ্য 行かされる; Group 2-এ 食べさせられる।": "Karaniwang may pag-aatubili, hirap, o sama ng loob. Sa Group 1: 行く→行かせられる/kolokyal na 行かされる; sa Group 2: 食べさせられる.", "させる = করানো/করতে দেওয়া; られる = করা হলো; させられる = করাতে বাধ্য করা হলো। ～ように言われた নির্দেশ পেয়েছি, কিন্তু বাস্তবে বাধ্য হয়ে করেছি—এ জোর নেই।": "させる = ipagawa/pahintulutang gawin; られる = ginawa sa; させられる = pinilit na ipagawa. Ang ～ように言われた ay nangangahulugang sinabihan akong gawin, ngunit walang diin na \"napilitan akong gawin ito sa aktuwal\".", "দুই তালা: させ (করানো) + られる (আমার ওপর হলো) = বাধ্য হলাম।": "Dalawang kandado: させ (ipagawa) + られる (ginawa sa akin) = napilitan ako.", "ছোটবেলায় এমন একটি কাজ যা তোমাকে জোর করে করানো হতো, させられました দিয়ে বলো।": "Sabihin ang isang bagay na pinilit sa iyong gawin noong bata ka pa, gamit ang させられました.", "নিজের অনুভূতি নয়—অন্য ব্যক্তির বাইরে দেখা আচরণ থেকে “সে এমন অনুভব করছে” বোঝায়। 感情 adjective-কে observable action বানায়।": "Hindi sariling damdamin — mula sa panlabas na nakikitang kilos ng ibang tao, ipinapakita nito na \"ganito ang nararamdaman niya\". Ginagawa nitong observable action ang 感情 adjective.", "私-এর সরাসরি অনুভূতিতে সাধারণত うれしい／怖い বলি; তৃতীয় ব্যক্তিতে うれしがっている／怖がっている। ～たい→～たがる-ও একই দৃষ্টিভঙ্গি।": "Para sa direktang damdamin ng 私, karaniwang sinasabi ang うれしい／怖い; para sa ikatlong tao, うれしがっている／怖がっている. Ang ～たい→～たがる ay parehong pananaw din.", "～そうだ appearance হতে পারে কিন্তু মুহূর্তের impression; ～がる আচরণের মাধ্যমে অনুভূতির pattern। ～と思っている হলে তার চিন্তা জানা/উদ্ধৃত।": "Ang ～そうだ ay maaaring appearance ngunit panandaliang impression; ang ～がる ay pattern ng damdamin sa pamamagitan ng kilos. Ang ～と思っている ay nangangahulugang alam/sinasipi ang kanyang iniisip.", "হৃদয় দেখা যায় না, আচরণ দেখা যায়—অন্যের হৃদয়ের ওপর “がる ক্যামেরা” বসাও।": "Hindi nakikita ang puso, ngunit nakikita ang kilos — ilagay ang \"がる camera\" sa puso ng iba.", "এক শিশু কুকুর দেখে ভয় পাচ্ছে—怖がっています দিয়ে বলো।": "Isang bata ang natatakot nang makakita ng aso — sabihin ito gamit ang 怖がっています.", "A শেষ হওয়ার ঠিক মুহূর্তেই B হঠাৎ ঘটে। সময়ের ফাঁক প্রায় শূন্য এবং B সাধারণত অনিয়ন্ত্রিত/অপ্রত্যাশিত।": "Sa mismong sandaling matapos ang A, biglang nangyayari ang B. Halos walang pagitan sa oras, at ang B ay karaniwang hindi kontrolado/hindi inaasahan.", "B-তে বক্তার ইচ্ছা, আদেশ বা পরিকল্পনা সাধারণত আসে না। একই ঘটনার স্বাভাবিক ধারাবাহিকতা নয়—surprise দরকার।": "Sa B, karaniwang hindi pumapasok ang kagustuhan, utos, o plano ng nagsasalita. Hindi ito natural na daloy ng iisang pangyayari — kailangan ng surprise.", "～と、～た discovery-তে নতুন কিছু দেখা যায়; ～たとたん shock-এর মুহূর্ত। ～たらより সময়ের আকস্মিকতা অনেক শক্ত।": "Sa ～と、～た discovery ay may bagong nakikita; ang ～たとたん ay ang sandali ng shock. Kung ikukumpara sa ～たら, mas matindi ang biglaan ng oras dito.", "দরজা বন্ধ—“টান!” শব্দ—সঙ্গে সঙ্গে আলো নিভে গেল। “টান” = とたん।": "Nagsara ang pinto — \"kalabog!\" — at kasabay nito ay namatay ang ilaw. Ang \"kalabog\" = とたん.", "বাইরে বের হতেই বৃষ্টি শুরু হলো—たとたん দিয়ে বলো।": "Pagkalabas mo pa lang ay nagsimulang umulan — sabihin ito gamit ang たとたん.", "কোনো কাজ/ঘটনা আচমকা ফেটে শুরু হওয়া বোঝায়। Verb-stem + 出す যেন ভিতরের action হঠাৎ বাইরে বেরিয়ে এল।": "Ipinapakita nito ang isang aksyon/pangyayari na biglang sumabog at nagsimula. Ang Verb-stem + 出す ay parang aksyon sa loob na biglang lumabas.", "泣き出す・笑い出す・降り出す-এর মতো sudden onset-এ খুব স্বাভাবিক। বক্তার শান্ত পরিকল্পিত শুরুতে 始める বেশি নিরপেক্ষ।": "Napakanatural nito sa sudden onset tulad ng 泣き出す・笑い出す・降り出す. Para sa mahinahon at planadong pagsisimula ng nagsasalita, mas neutral ang 始める.", "読み始める = পড়া শুরু করা; 泣き出す = হঠাৎ কেঁদে ওঠা। “হঠাৎ” অনুভূতি না থাকলে 出す বেছে নিও না।": "読み始める = simulan ang pagbabasa; 泣き出す = biglang mapaiyak. Kung walang pakiramdam na \"biglaan\", huwag piliin ang 出す.", "বাক্সের ভেতর থেকে action “বের হলো”—出す-এর kanji-ই memory picture।": "Ang action ay \"lumabas\" mula sa loob ng kahon — ang kanji mismo ng 出す ang memory picture.", "ক্লাসে সবাই হঠাৎ হাসতে শুরু করল—笑い出した দিয়ে বলো।": "Biglang nagsimulang tumawa ang lahat sa klase — sabihin ito gamit ang 笑い出した.", "意向形 দিয়ে action-এর ঠিক আগের প্রস্তুতি/চেষ্টা ধরে: “করতে যাচ্ছিল/করার চেষ্টা করছে।” কাজটি শেষ হয়েছে কি না নিশ্চিত নয়।": "Gamit ang 意向形, hinuhuli nito ang paghahanda/pagsisikap bago mismo ang aksyon: \"magsisimula na sana/sinusubukang gawin\". Hindi tiyak kung natapos ang aksyon o hindi.", "～ようとしたが… হলে চেষ্টা ব্যর্থ হওয়ার গল্পে বেশি আসে। Non-volitional subject-এ imminent change-ও হতে পারে: 日が沈もうとしている।": "Ang ～ようとしたが… ay mas madalas sa mga kuwento ng nabigong pagsisikap. Sa non-volitional subject, maaari rin itong imminent change: 日が沈もうとしている.", "～つもりだ স্থির পরিকল্পনা; ～ようと思う intention; ～ようとする action শুরুর ঠিক মুহূর্ত বা বাস্তব চেষ্টা।": "Ang ～つもりだ ay matatag na plano; ang ～ようと思う ay intention; ang ～ようとする ay ang sandali bago magsimula ang action o ang aktuwal na pagsisikap.", "দৌড় শুরুর লাইনে পা তুলেছে কিন্তু এখনো ছুটেনি—এই মাঝের frame হলো ようとする।": "Nasa starting line ng takbuhan, nakataas na ang paa ngunit hindi pa tumatakbo — ang gitnang frame na iyon ang ようとする.", "ট্রেনে উঠতে যাচ্ছিলে, কিন্তু দরজা বন্ধ হলো—ようとしたとき দিয়ে বলো।": "Sasakay ka na sana sa tren, ngunit nagsara ang pinto — sabihin ito gamit ang ようとしたとき.", "একটি ঘটনা সবসময় নয়, মাঝে মাঝে সম্ভাব্য/বাস্তব হয়—এই exception-কে যোগ করে। も “এমনটাও” ভাব দেয়।": "Idinaragdag nito ang exception na ang isang pangyayari ay hindi palaging nangyayari, ngunit paminsan-minsan ay posible/aktuwal. Ang も ay nagbibigay ng pakiramdam na \"may mga pagkakataon ding ganito\".", "習慣/সম্ভাবনার ওঠানামায় ব্যবহৃত হয়। অতীতের একবারের ঘটনা বলতে ことがある নয়; Vたことがある experience-এর আলাদা pattern।": "Ginagamit ito sa pabago-bagong 習慣/posibilidad. Sa pagsasabi ng isang pangyayaring minsan lang nangyari sa nakaraan, hindi ito ことがある; ang Vたことがある ay ibang pattern para sa experience.", "Vることがある = কখনো হয়; Vたことがある = আগে করার অভিজ্ঞতা আছে; Vる可能性がある = formal সম্ভাবনা।": "Vることがある = nangyayari kung minsan; Vたことがある = may karanasan nang gawin noon; Vる可能性がある = pormal na posibilidad.", "ক্যালেন্ডারের বেশির ভাগ দিন সাদা, দু-একটি দিন রঙিন—সেই “কখনো কখনো”-ই こともある।": "Karamihan sa mga araw sa kalendaryo ay puti, ngunit may isa o dalawang araw na may kulay — ang \"kung minsan\" na iyon ang こともある.", "ব্যস্ত হলে তুমি কখনো নাশতা না করেও বের হও—こともあります দিয়ে বলো।": "Kapag abala ka, kung minsan ay lumalabas ka nang hindi nag-aalmusal — sabihin ito gamit ang こともあります.", "কাউকে কোনো কাজ করতে দেওয়া/করিয়ে আগাম অবস্থা তৈরি করে রাখা। させる agent বদলায়, ておく future preparation যোগ করে।": "Pinapayagan/pinapagawa sa isang tao ang isang aksyon upang lumikha ng isang kalagayan nang maaga. Binabago ng させる ang agent, at idinaragdag ng ておく ang future preparation.", "অনুমতি ও নির্দেশ—দুই reading context-এ সম্ভব: 子どもを遊ばせておく = শিশুকে খেলতে দিয়ে রাখা; 部下に準備させておく = কর্মীকে প্রস্তুত করিয়ে রাখা।": "Posible ang dalawang reading depende sa context — pahintulot at utos: 子どもを遊ばせておく = hayaang maglaro ang bata; 部下に準備させておく = ipahanda sa nasasakupan at iwanang handa.", "～ておく-এ subject নিজে প্রস্তুতি করে; ～させておく-এ অন্য কাউকে করায়/করতে দেয়। ～させてもらう-তে আমি অনুমতি পাই।": "Sa ～ておく, ang subject mismo ang naghahanda; sa ～させておく, ipinapagawa niya ito sa iba o pinapayagan niya ang iba. Sa ～させてもらう, ako ang tumatanggap ng pahintulot.", "আগামীকালের জন্য একটি মানুষকে “action অবস্থায় রেখে দাও”—させ + ておく।": "\"Iwan ang isang tao sa action state\" para sa bukas — させ + ておく.", "মিটিংয়ের আগে সহকর্মীকে কাগজ প্রস্তুত করিয়ে রাখবে—বাক্য বানাও।": "Bago ang meeting, ipahahanda mo sa katrabaho mo ang mga papel — bumuo ng pangungusap.", "অন্যের action আমার ওপর passive হয়ে এসেছে এবং てしまう সেটিকে অনিচ্ছাকৃত ক্ষতি/দুঃখ হিসেবে সম্পূর্ণ করেছে।": "Ang aksyon ng iba ay dumating sa akin bilang passive, at tinapos ito ng てしまう bilang hindi sinasadyang pinsala/kalungkutan.", "শুধু passive fact নয়; বক্তার affected feeling গুরুত্বপূর্ণ। 財布を盗まれてしまった-তে চুরি এবং ক্ষতির আফসোস দুটোই আছে।": "Hindi lang passive fact; mahalaga ang affected feeling ng nagsasalita. Sa 財布を盗まれてしまった ay naroon kapwa ang pagnanakaw at ang panghihinayang sa pagkawala.", "盗まれた = চুরি হয়েছে (fact); 盗まれてしまった = চুরি হয়ে গিয়ে বিপদ/দুঃখ হয়েছে। ～てしまう active হলেও ভুল/সম্পূর্ণতা বোঝাতে পারে।": "盗まれた = ninakaw (fact); 盗まれてしまった = ninakaw at nagdulot ng problema/kalungkutan. Kahit active ang ～てしまう, maaari rin itong mangahulugan ng pagkakamali/kabuoan.", "Passive-এর ওপর “দুঃখের সিল” しまう লাগাও—られてしまう।": "Ilagay ang \"selyo ng kalungkutan\" na しまう sa ibabaw ng passive — られてしまう.", "কেউ তোমার ছাতা নিয়ে যাওয়ায় তুমি সমস্যায় পড়েছ—এই pattern দিয়ে বলো।": "May kumuha ng payong mo at nagkaproblema ka — sabihin ito gamit ang pattern na ito.", "কোন পদ্ধতি, প্রযুক্তি বা মাধ্যম ব্যবহার করে ফলটি হলো—সেই tool/channel দেখায়। NによるN হলে পরের noun-কে পদ্ধতি অনুযায়ী বর্ণনা করে।": "Ipinapakita nito kung anong paraan, teknolohiya, o midyum ang ginamit upang makamit ang resulta — ang tool/channel na iyon. Kung NによるN, inilalarawan nito ang sumusunod na noun ayon sa paraan.", "লিখিত ও formal ভাষায় বেশি। মানুষকে intermediary হিসেবে বললে ～を通して বেশি natural হতে পারে; সরাসরি physical tool-এ で সহজ।": "Mas madalas ito sa nakasulat at formal na wika. Kapag tao ang intermediary, maaaring mas natural ang ～を通して; para sa direktang physical tool, madali ang で.", "電車で行く = সাধারণ tool; インターネットによる投票 = formal method; 友人を通して知る = বন্ধুর মাধ্যমে পরিচয়।": "電車で行く = karaniwang tool; インターネットによる投票 = formal method; 友人を通して知る = makilala sa pamamagitan ng kaibigan.", "による-কে একটি “METHOD” লেবেল ভাবো—কাজটি কোন ব্যবস্থায় হলো তা বলে।": "Isipin ang による bilang isang label na \"METHOD\" — sinasabi nito kung sa anong sistema nagawa ang aksyon.", "অনলাইনের মাধ্যমে আবেদন করা যায়—によって／による ব্যবহার করে বলো।": "Maaaring mag-apply sa pamamagitan ng online — sabihin ito gamit ang によって／による.", "কোন ব্যক্তি/বস্তু/মতামতের দিকে action, attitude বা contrast যাচ্ছে—তার target চিহ্নিত করে।": "Minamarkahan nito ang target kung saan patungo ang action, attitude, o contrast — kung aling tao/bagay/opinyon.", "人に対して + আচরণ; Aに対してB + বিপরীততা; Nに対するN + noun modification। “বিরুদ্ধে” সবসময় নয়—“প্রতি”ও হতে পারে।": "人に対して + kilos; Aに対してB + pagkakaiba/contrast; Nに対するN + noun modification. Hindi ito palaging \"laban sa\" — maaari rin itong \"tungo sa/para sa\".", "～について = বিষয় সম্পর্কে; ～にとって = কার দৃষ্টিতে; ～に対して = কার/কিসের দিকে response বা বিপরীত দিক।": "～について = tungkol sa paksa; ～にとって = sa pananaw ng sinuman; ～に対して = tugon o magkasalungat na direksyon tungo sa isang tao/bagay.", "対-এর ছবি দুই দিক মুখোমুখি—একদিকে target, অন্যদিকে action/contrast।": "Ang larawan ng 対 ay dalawang panig na magkaharap — sa isang panig ang target, sa kabila ang action/contrast.", "গ্রাহকের প্রতি ভদ্র হতে হবে—お客様に対して দিয়ে বলো।": "Kailangang maging magalang sa mga customer — sabihin ito gamit ang お客様に対して.", "কারণ A থেকে ফল B হয়েছে—লিখিত, নিরপেক্ষ ও তুলনামূলকভাবে objective ভঙ্গি। ফলটি প্রায়ই অসুবিধা/ঘটনা, তবে সবসময় negative নয়।": "Mula sa sanhing A ay naganap ang resultang B — nakasulat, neutral, at medyo objective ang estilo. Ang resulta ay madalas na abala/pangyayari, ngunit hindi palaging negative.", "Nのため、なAなため、plain form＋ため। বক্তার তাৎক্ষণিক ব্যক্তিগত অজুহাতে から／ので বেশি natural; notice/news-এ ため বেশি।": "Nのため、なAなため、plain form＋ため. Para sa pansamantalang personal na dahilan ng nagsasalita, mas natural ang から／ので; sa notice/news, mas madalas ang ため.", "～ので নরম দৈনন্দিন কারণ; ～ため formal objective cause; ～せいで খারাপ ফলের blame; ～おかげで ভালো ফলের gratitude।": "～ので ay malambot na pang-araw-araw na sanhi; ～ため ay formal objective cause; ～せいで ay paninisi sa masamang resulta; ～おかげで ay pasasalamat sa magandang resulta.", "ট্রেনের notice কল্পনা করো: 台風のため、運休します—এটাই ため-এর formal কণ্ঠ।": "Isipin ang isang notice sa tren: 台風のため、運休します — iyan ang formal na tinig ng ため.", "তুষারের কারণে ট্রেন দেরি করেছে—ため ব্যবহার করে formal বাক্য বলো।": "Nahuli ang tren dahil sa niyebe — bumuo ng formal na pangungusap gamit ang ため.", "একটি unit/ব্যক্তি/বার অনুযায়ী সংখ্যা, মূল্য বা বরাদ্দ ভাগ করে: “প্রতি…”। এখানে つき মানে “একটির সঙ্গে যুক্ত হিসেবে”।": "Hinahati nito ang bilang, presyo, o alokasyon ayon sa isang unit/tao/pagkakataon: \"bawat…\". Ang つき dito ay nangangahulugang \"bilang nakakabit sa isa\".", "Nにつき＋quantity সবচেয়ে স্বাভাবিক। Notice-এর “কারণে” অর্থের Nにつき (工事中につき) আলাদা usage—context দেখবে।": "Pinakanatural ang Nにつき＋quantity. Ang Nにつき na nangangahulugang \"dahil sa\" sa mga notice (工事中につき) ay ibang usage — tingnan ang context.", "一人につき二枚 = প্রতি ব্যক্তিতে দুইটি; 一枚ずつ = একেকটি করে distribution। 毎- prefix সময়ের নিয়মিততা দেখায়।": "一人につき二枚 = dalawa bawat tao; 一枚ずつ = tig-iisa sa pamamahagi. Ipinapakita ng 毎- prefix ang regularidad sa oras.", "প্রতিটি টিকিটের সঙ্গে দুইটি coupon “attached”—attached = つき।": "\"Nakakabit\" ang dalawang coupon sa bawat ticket — attached = つき.", "একজন সর্বোচ্চ দুইটি টিকিট কিনতে পারবে—お一人につき দিয়ে বলো।": "Ang isang tao ay maaaring bumili ng hanggang dalawang ticket — sabihin ito gamit ang お一人につき.", "নির্দেশ, পরিকল্পনা, পূর্বাভাস বা দেখা নমুনার সঙ্গে ফল/কাজ একদম মিলেছে: “যেভাবে… ঠিক সেভাবে।”": "Eksaktong tumugma ang resulta/aksyon sa utos, plano, prediksyon, o nakitang halimbawa: \"kung paano… ay eksaktong ganoon din.\"", "Vるとおり = যেভাবে হবে/বলা হয়; Vたとおり = যেভাবে হয়েছিল/বলা হয়েছিল; Nどおり-ও হয়। Particle に থাকলে adverb, の হলে noun modifier।": "Vるとおり = kung paano ito mangyayari/sinasabi; Vたとおり = kung paano ito nangyari/sinabi; maaari rin ang Nどおり. Kung may particle na に, ito ay adverb; kung の, ito ay noun modifier.", "～ように “যেমন” বলতে পারে কিন্তু exact match দুর্বল; ～とおり-তে model ও result-এর correspondence স্পষ্ট। ～まま শুধু অবস্থা না বদলানো।": "Maaari ring sabihin ng ～ように ang \"tulad ng\", ngunit mahina ang exact match; sa ～とおり ay malinaw ang correspondence ng model at result. Ang ～まま ay simpleng hindi pagbabago ng kalagayan.", "ট্রেসিং পেপারে নিচের রেখা হুবহু অনুসরণ করছ—এই exact copy-ই とおり。": "Sinusundan mo nang eksakto ang guhit sa ilalim gamit ang tracing paper — ang exact copy na iyon ang とおり.", "শিক্ষক যেভাবে বলেছেন সেভাবে লিখেছ—言われたとおりに দিয়ে বলো।": "Isinulat mo ito kung paano sinabi ng guro — sabihin ito gamit ang 言われたとおりに.", "কোনো ব্যক্তি/সংস্থা/অভিজ্ঞতাকে bridge বানিয়ে অন্য মানুষ, তথ্য বা সুযোগের সঙ্গে সংযোগ হয়েছে।": "Ginagawa nitong tulay ang isang tao/organisasyon/karanasan upang makakonekta sa ibang tao, impormasyon, o pagkakataon.", "মাধ্যমটি সাধারণ tool নয়; intermediary/channel-এর অনুভূতি থাকে। 人を通して, 紹介を通して, 経験を通して খুব স্বাভাবিক।": "Ang midyum ay hindi karaniwang tool; may pakiramdam ito ng intermediary/channel. Napakanatural ang 人を通して, 紹介を通して, 経験を通して.", "～によって method/cause/agent; ～を通して intermediary বা entire period—এখানে “মাধ্যম” অর্থ।": "～によって ay method/cause/agent; ～を通して ay intermediary o entire period — dito ang kahulugan ay \"sa pamamagitan ng midyum\".", "একটি টানেলের মধ্য দিয়ে A থেকে B-তে পৌঁছাও—通して মানে সেই bridge।": "Dumaan ka sa isang tunnel mula A patungong B — ang 通して ay ang tulay na iyon.", "বন্ধুর মাধ্যমে বর্তমান চাকরির খবর জেনেছ—友達を通して দিয়ে বলো।": "Nalaman mo ang tungkol sa kasalukuyan mong trabaho sa pamamagitan ng isang kaibigan — sabihin ito gamit ang 友達を通して.", "একটি category বোঝাতে representative example সামনে আনে: “N-এর মতো…”। N নিজেই model; ような পরের noun-কে বর্ণনা করে।": "Naglalabas ito ng isang representative example upang ipaliwanag ang isang category: \"tulad ng N…\". Ang N mismo ang model; inilalarawan ng ような ang sumusunod na noun.", "NのようなN = N-এর মতো N; NのようにV/A = N-এর মতো করে/ভাবে। এটি exact identity নয়, similarity/example।": "NのようなN = N na tulad ng N; NのようにV/A = sa paraang tulad ng N. Hindi ito exact identity, kundi similarity/example.", "～みたいな কথ্য; ～のような নিরপেক্ষ/লিখিত; ～らしい সত্যিকারের বৈশিষ্ট্য; ～っぽい surface tendency।": "～みたいな ay kolokyal; ～のような ay neutral/nakasulat; ～らしい ay tunay na katangian; ～っぽい ay surface tendency.", "একটি নমুনা কার্ড দেখিয়ে বলছ: “এইটার মতো”—Nのような।": "Ipinapakita mo ang isang sample card at sinasabi: \"tulad nito\" — Nのような.", "Tokyo-এর মতো বড় শহর—東京のような দিয়ে একটি বাক্য বানাও।": "Isang malaking lungsod tulad ng Tokyo — bumuo ng pangungusap gamit ang 東京のような.", "তথ্যের source প্রথমে চিহ্নিত করে, তারপর সাধারণত そうだ／ということだ／らしい দিয়ে report দেয়।": "Una nitong minamarkahan ang source ng impormasyon, pagkatapos ay karaniwang nagbibigay ng report gamit ang そうだ／ということだ／らしい.", "সংবাদ, রিপোর্ট, আবহাওয়ার পূর্বাভাসের মতো source-ভিত্তিক কথায় formal। Source মানুষও হতে পারে: 先生によれば。": "Formal ito sa mga pahayag na batay sa source tulad ng balita, ulat, at taya ng panahon. Maaari ring tao ang source: 先生によれば.", "～によれば source; ～について topic; ～によって cause/method/agent। পরে report marker না থাকলে বাক্য অসম্পূর্ণ শোনাতে পারে।": "～によれば ay source; ～について ay topic; ～によって ay cause/method/agent. Kung walang report marker pagkatapos, maaaring makarinig na hindi kumpleto ang pangungusap.", "খবরের কাগজের ওপর “SOURCE:” লিখে পাশে によれば বসাও।": "Isulat ang \"SOURCE:\" sa ibabaw ng pahayagan at ilagay ang によれば sa tabi nito.", "আবহাওয়ার খবর অনুযায়ী কাল বৃষ্টি হবে—天気予報によれば দিয়ে বলো।": "Ayon sa balita tungkol sa panahon, uulan bukas — sabihin ito gamit ang 天気予報によれば.", "নিজে প্রত্যক্ষ না করা তথ্যকে neutral report হিসেবে অন্যকে জানায়: “জানা গেছে/শুনেছি যে…”।": "Ipinapahayag nito sa iba bilang neutral report ang impormasyong hindi personal na nasaksihan: \"napag-alaman/narinig na…\".", "Information source আগে によれば／によると দিয়ে আসতে পারে। N/なA-তে だ বজায় থাকে: 休みだということです।": "Maaaring mauna ang information source gamit ang によれば／によると. Sa N/なA ay nananatili ang だ: 休みだということです.", "～そうです (hearsay) বেশি সংক্ষিপ্ত; ～ということです formal report; ～ということ nominalizer হলেও report meaning context-নির্ভর।": "Ang ～そうです (hearsay) ay mas maikli; ang ～ということです ay formal report; kahit nominalizer ang ～ということ, ang report meaning ay depende sa context.", "একজনের মুখ থেকে কথা speech-bubble হয়ে তোমার মুখে এসেছে—bubble-এর label ということです।": "Ang mga salita mula sa bibig ng isang tao ay dumating sa iyong bibig bilang speech-bubble — ang label ng bubble ay ということです.", "স্কুল থেকে শুনেছ আগামী সপ্তাহে ছুটি—এই pattern-এ report করো।": "Narinig mo mula sa paaralan na may bakasyon sa susunod na linggo — i-report ito gamit ang pattern na ito.", "কথা, লেখা, গবেষণা বা প্রশ্নের topic নির্ধারণ করে: “N বিষয়ে/সম্পর্কে।” Action সাধারণত জানা, বলা, ভাবা, তদন্ত করা।": "Tinutukoy nito ang topic ng pananalita, pagsulat, pananaliksik, o tanong: \"tungkol sa N\". Ang action ay karaniwang pag-alam, pagsasabi, pag-iisip, o pagsisiyasat.", "NについてV; NについてのN। মানুষ target হলে শুধু “সম্পর্কে” অর্থে চলে; মানুষকে আচরণের target করতে に対して দরকার।": "NについてV; NについてのN. Kung tao ang target, gumagana ito sa kahulugang \"tungkol sa\" lamang; upang gawing target ng kilos ang isang tao, kailangan ang に対して.", "～に関して আরও formal; ～に対して response/contrast; ～にとって viewpoint।": "Ang ～に関して ay mas formal; ang ～に対して ay response/contrast; ang ～にとって ay viewpoint.", "একটি ফাইলের cover-এ topic-এর নাম লিখে দাও—Nについて হলো সেই cover label।": "Isulat ang pangalan ng topic sa cover ng isang file — ang Nについて ay ang cover label na iyon.", "জাপানে কাজ করার নিয়ম সম্পর্কে জানতে চাই—について知りたい দিয়ে বলো।": "Gusto kong malaman ang tungkol sa mga patakaran sa pagtatrabaho sa Japan — sabihin ito gamit ang について知りたい.", "～ている-এর casual spoken contraction। চলমান কাজ, অভ্যাস বা resulting state—মূল ている-এর অর্থই থাকে, শুধু শব্দ ছোট হয়।": "Kolokyal na spoken contraction ng ～ている. Nagpapatuloy na aksyon, nakagawian, o resulting state — nananatili ang kahulugan mismo ng ている, umiikli lang ang salita.", "食べている→食べてる; 読んでいる→読んでる। Formal speech/লেখায় contraction না করাই নিরাপদ। ておく→とく-এর সঙ্গে গুলিও না।": "食べている→食べてる; 読んでいる→読んでる. Sa formal speech/pagsulat, mas ligtas na huwag gumamit ng contraction. Huwag itong ipagkamali sa ておく→とく.", "てる = ている; てた = ていた; てました = ていました-এর polite spoken contraction।": "てる = ている; てた = ていた; てました = polite spoken contraction ng ていました.", "ている থেকে মাঝের い “চুপচাপ বাড়ি গেল”—বাকি てる।": "Ang い sa gitna ng ている ay \"tahimik na umuwi\" — ang natira ay てる.", "বন্ধুকে “এখন কী করছ?” এবং উত্তর casual てる দিয়ে বলো।": "Tanungin ang kaibigan mo ng \"Ano ang ginagawa mo ngayon?\" at sagutin ito gamit ang casual na てる.", "なければならない-এর casual সংক্ষিপ্ত বাধ্যতা: “করতেই হবে।” পুরো ফল না বললেও listener বুঝে নেয়—না করলে সমস্যা।": "Maikling casual na anyo ng なければならない na nagpapahayag ng obligasyon: \"kailangan talagang gawin.\" Kahit hindi sabihin ang buong resulta, nauunawaan ng listener — magkakaproblema kung hindi gagawin.", "Vない থেকে い বাদ + きゃ: 行かなきゃ。আরেক casual form なくちゃ। Teacher/manager-কে formalভাবে なければなりません ব্যবহার করো।": "Alisin ang い mula sa Vない at idagdag ang きゃ: 行かなきゃ. Isa pang casual form ay なくちゃ. Para sa teacher/manager, gamitin ang pormal na なければなりません.", "～べき = নৈতিক/strong advice; ～なきゃ = বাস্তব necessity; ～ないと-ও casual “না হলে” থেকে obligation।": "～べき = moral/masidhing payo; ～なきゃ = aktuwal na necessity; ～ないと ay casual na obligasyon din mula sa \"kung hindi…\".", "লম্বা なければならない দৌড়ে ক্লান্ত হয়ে ছোট হলো—なきゃ।": "Napagod sa pagtakbo ang mahabang なければならない at umikli — なきゃ.", "আজ রাতে homework শেষ করতেই হবে—casual なきゃ দিয়ে বলো।": "Kailangan mong tapusin ang homework ngayong gabi — sabihin ito gamit ang casual na なきゃ.", "ভুলে যাওয়া তথ্য নিজের স্মৃতি থেকে টেনে নিশ্চিত করে: “কী ছিল যেন?” প্রশ্নটি listener-কেও হতে পারে, নিজেকেও।": "Kinukumpirma nito ang nakalimutang impormasyon sa pamamagitan ng paghugot mula sa sariling alaala: \"Ano nga iyon?\" Ang tanong ay maaaring sa listener o sa sarili.", "আগে জানা ছিল—এখন মনে পড়ছে না। একেবারে নতুন তথ্য জিজ্ঞেস করতে ব্যবহার করো না। Past/だ form বেশি দেখা যায়: 何時だっけ、行ったっけ。": "Alam mo ito noon — ngayon ay hindi mo na maalala. Huwag itong gamitin sa pagtatanong ng ganap na bagong impormasyon. Mas madalas makita ang Past/だ form: 何時だっけ、行ったっけ.", "～かな নতুন সন্দেহ/নিজের ভাবনা; ～っけ পুরোনো memory check; ～でしょうか ভদ্র তথ্য প্রশ্ন।": "～かな ay bagong pagdududa/sariling pag-iisip; ～っけ ay pag-check ng lumang memory; ～でしょうか ay magalang na tanong tungkol sa impormasyon.", "মাথার ড্রয়ার খুলে বলছ “কোথায় রেখেছিলাম…っけ?”—এটি memory-search sound।": "Binubuksan mo ang drawer ng iyong ulo at sinasabi mong \"Saan ko nga inilagay iyon…っけ?\" — ito ang memory-search sound.", "পরীক্ষা কয় তারিখ ছিল মনে করতে 何日だっけ দিয়ে বলো।": "Sabihin kung anong petsa nga ang pagsusulit, gamit ang 何日だっけ upang subukang alalahanin.", "একটি সম্ভাবনা সরাসরি না বলে “হয়তো এমনও?” ভঙ্গিতে হালকা, playful বা tentative অনুমান করে।": "Hindi direktang sinasabi ang isang posibilidad, kundi magaan, playful, o tentative na hula sa estilong \"baka ganito rin?\".", "Intonation ও context গুরুত্বপূর্ণ। সত্যি অভিযোগ না করে teasing/soft suggestion-এ ভালো; formal situation-এ避ける।": "Mahalaga ang intonation at context. Mahusay ito sa teasing/soft suggestion nang hindi talaga nagbibintang; sa formal na sitwasyon, 避ける — iwasan ito.", "～かもしれない neutral possibility; ～たりして casual “হয়তো আবার…”; ～たり～たり একাধিক action-এর list—সম্পূর্ণ আলাদা।": "～かもしれない ay neutral possibility; ～たりして ay casual na \"baka naman…\"; ～たり～たり ay list ng maraming action — ganap na iba.", "মুখে ছোট হাসি দিয়ে “まさか、好きだったりして？”—এই playful bubble মনে রাখো।": "Nakangiti nang bahagya habang sinasabi ang \"まさか、好きだったりして？\" — tandaan ang playful bubble na ito.", "বন্ধু দেরি করেছে—“হয়তো ঘুমিয়ে পড়েছে?” たりして দিয়ে বলো।": "Huli ang kaibigan mo — \"Baka nakatulog siya?\" Sabihin ito gamit ang たりして.", "～ても-এর খুব casual emphatic form: বাধা A সত্য হলেও ফল B বদলাবে না—“যদিও… তবুও।”": "Napakakasual at emphatic na anyo ng ～ても: kahit totoo ang hadlang na A, hindi magbabago ang resultang B — \"kahit… pa rin.\"", "Vたって, いAくたって, N/なAだって। ঘনিষ্ঠ কথায় চলে; formal writing-এ ～ても／でも।": "Vたって, いAくたって, N/なAだって. Gumagana ito sa malapitang usapan; sa formal writing, ～ても／でも.", "～ても neutral concession; ～たって casual ও জোরালো; ～からといって “শুধু এই কারণেই” ভুল সিদ্ধান্ত ঠেকায়।": "～ても ay neutral concession; ～たって ay casual at masidhi; ～からといって ay pumipigil sa maling konklusyon na \"dahil lang sa kadahilanang ito\".", "て-form casual কথায় শক্ত হয়ে たって—“তবুও আমি করব!” এমন দৃঢ় কণ্ঠ।": "Ang て-form ay tumitigas sa casual na pananalita at nagiging たって — matatag na tinig na \"Gagawin ko pa rin!\".", "বৃষ্টি হলেও কাজে যেতে হবে—たって দিয়ে casual বাক্য বলো।": "Kahit umulan ay kailangan mong pumasok sa trabaho — bumuo ng casual na pangungusap gamit ang たって.", "বক্তার ব্যক্তিগত দৃঢ় বিশ্বাস: “নিশ্চয়ই এটাই/অবশ্যই হবে।” প্রমাণ দেখানো জরুরি নয়; conviction খুব শক্ত।": "Matibay na personal na paniniwala ng nagsasalita: \"tiyak na ito iyon/mangyayari talaga.\" Hindi kailangang magpakita ng ebidensya; napakatibay ng conviction.", "Casual/emotional judgement-এ বেশি। অন্যের বিরুদ্ধে তাড়াহুড়ো করে বললে কঠোর বা unfair শোনাতে পারে।": "Mas madalas ito sa casual/emotional judgement. Kung padalos-dalos itong sasabihin laban sa iba, maaaring makarinig na malupit o unfair.", "～はずだ যুক্তি/তথ্যভিত্তিক expectation; ～に違いない evidence-ভিত্তিক strong inference; ～に決まっている বক্তার নিশ্চিত, আবেগী conviction।": "～はずだ ay expectation batay sa lohika/impormasyon; ～に違いない ay strong inference batay sa evidence; ～に決まっている ay tiyak at emosyonal na conviction ng nagsasalita.", "মাথায় সিদ্ধান্তের স্ট্যাম্প: 決 = decided—“আর কোনো উত্তরই নেই।”": "Selyo ng desisyon sa ulo: 決 = decided — \"wala nang ibang sagot.\"", "বন্ধুর বানানো খাবার নিশ্চয়ই সুস্বাদু—に決まっている দিয়ে বলো।": "Tiyak na masarap ang lutong pagkain ng kaibigan mo — sabihin ito gamit ang に決まっている.", "স্বরের ওপর অর্থ বদলায়: জানা সত্য চোখে পড়লে “দেখো, আছে তো!”, অথবা আচরণে অসন্তোষ হলে “এটা ঠিক নয়!”।": "Nagbabago ang kahulugan ayon sa tono: kapag nakita ang isang alam na katotohanan, \"Ayan, mayroon naman pala!\"; o kapag hindi nasisiyahan sa kilos, \"Hindi ito tama!\"", "Rising intonation confirmation হতে পারে; falling/strong intonation blame বা discovery। Formal প্রশ্নের ではありませんか-এর সমান সবসময় নয়।": "Ang rising intonation ay maaaring confirmation; ang falling/strong intonation ay paninisi o discovery. Hindi ito palaging katumbas ng ではありませんか sa formal na tanong.", "～じゃない？ নরম confirmation-ও হতে পারে; じゃないか পুরুষালি/জোরালো; plain negative copula じゃない শুধু “নয়”।": "Ang ～じゃない？ ay maaari ring malambot na confirmation; ang じゃないか ay mas masculine/masidhi; ang plain negative copula na じゃない ay simpleng \"hindi\".", "একই শব্দ, দুই মুখ: বিস্ময়ের চোখ “あるじゃない！” এবং ভ্রু কুঁচকে অভিযোগ “遅いじゃない！”।": "Iisang salita, dalawang mukha: mga matang nagulat na \"あるじゃない！\" at nakakunot-noong reklamo na \"遅いじゃない！\".", "হারানো চাবি চোখের সামনে পেয়ে discovery じゃない দিয়ে বলো।": "Natagpuan mo ang nawawalang susi sa harap ng iyong mga mata — sabihin ito gamit ang discovery na じゃない.", "Nは-এর casual topic version: “N-এর কথা বললে/যে N…”। Topic-টিকে কথোপকথনের সামনে আনে।": "Casual topic version ng Nは: \"kung pag-uusapan ang N / ang N kasi…\". Inilalabas nito ang topic sa unahan ng usapan.", "Noun-এর পরে সরাসরি って। Naming/quotation-এর という অর্থও হতে পারে; পরে predicate কী করছে দেখে নির্ধারণ করো।": "Direktang って pagkatapos ng noun. Maaari rin itong mangahulugan ng という para sa pagpapangalan/quotation; tingnan kung ano ang ginagawa ng predicate pagkatapos upang magpasya.", "田中さんって人 = という人 (নাম); 田中さんって親切だね = は (topic)। Rule 11-এর সঙ্গে form এক, function আলাদা।": "田中さんって人 = という人 (pangalan); 田中さんって親切だね = は (topic). Pareho ang form sa Rule 11, ngunit iba ang function.", "って একটি spotlight—যে noun-এর পরে বসে তাকে কথার মঞ্চে তুলে ধরে।": "Ang って ay isang spotlight — inilalagay nito sa entablado ng usapan ang noun na sinusundan nito.", "“জাপান বলতে সত্যিই পরিষ্কার দেশ”—日本って দিয়ে casual বাক্য বলো।": "\"Ang Japan, talagang malinis na bansa\" — bumuo ng casual na pangungusap gamit ang 日本って.", "দেখা লক্ষণ থেকে casual inference বা সরাসরি similarity: “মনে হচ্ছে/মতো।” বক্তার impression সামনে থাকে।": "Casual inference mula sa nakitang palatandaan o direktang similarity: \"mukhang/parang.\" Nasa unahan ang impression ng nagsasalita.", "N/なA-তে だ লাগে না: 学生みたいだ、静かみたいだ। NみたいなN, NみたいにV/A-ও হয়।": "Sa N/なA ay hindi idinaragdag ang だ: 学生みたいだ、静かみたいだ. Maaari rin ang NみたいなN, NみたいにV/A.", "～ようだ neutral/formal; ～みたいだ casual; ～らしい hearsay বা typical quality; ～そうだ surface appearance।": "～ようだ ay neutral/formal; ～みたいだ ay casual; ～らしい ay hearsay o typical quality; ～そうだ ay surface appearance.", "বন্ধুকে ছবি দেখিয়ে বলছ “猫みたい！”—casual resemblance-এর তাৎক্ষণিক শব্দ।": "Ipinapakita mo ang isang larawan sa kaibigan mo at sinasabi mong \"猫みたい！\" — ang agarang salita ng casual resemblance.", "আকাশ দেখে মনে হচ্ছে বৃষ্টি হবে—みたいだ দিয়ে বলো।": "Tumingin sa langit at sabihin ang \"mukhang uulan\" gamit ang みたいだ.", "অতীতে অন্য choice নিলে ভালো হতো—এখন আর বদলানো যায় না, তাই regret। ば condition + よかった positive evaluation।": "Mas mabuti sana kung ibang choice ang pinili sa nakaraan — hindi na ito mababago ngayon, kaya ito ay regret. ば condition + よかった positive evaluation.", "করিনি কিন্তু করা উচিত ছিল: 行けばよかった। করেছি কিন্তু না করাই ভালো ছিল: 行かなければよかった। সময় অবশ্যই অতীতের missed chance।": "Hindi ginawa ngunit dapat sana ginawa: 行けばよかった. Ginawa ngunit mas mabuti sana kung hindi ginawa: 行かなければよかった. Ang oras ay tiyak na isang missed chance sa nakaraan.", "～ばいい future advice; ～ばよかった past regret; ～ばいいのに অন্যকে নিয়ে criticism/wish।": "～ばいい ay future advice; ～ばよかった ay past regret; ～ばいいのに ay criticism/wish tungkol sa iba.", "পেছনের রাস্তার দিকে তাকিয়ে বলছ “ও পথ নিলে ভালো হতো”—past road = ばよかった।": "Tumingin sa daan sa likuran at sinasabi mong \"Mas mabuti sana kung iyon ang dinaanan ko\" — past road = ばよかった.", "আগে থেকে পড়াশোনা না করার একটি অনুশোচনা এই pattern-এ বলো।": "Sabihin ang isang panghihinayang na hindi ka nag-aral nang maaga, gamit ang pattern na ito.", "ばかり অন্য সবকিছুকে বাদ দিয়ে একই noun/action বেশি হচ্ছে—এই imbalance সামনে আনে। Criticism usage-এ “শুধু এটিই করে” ভাবটি মূল।": "Inilalabas ng ばかり sa unahan ang imbalance na ang parehong noun/action lang ang nangyayari, hindi kasama ang lahat ng iba pa. Sa criticism usage, ang \"ito lang ang ginagawa\" ang pangunahing pakiramdam.", "Nばかり, Vてばかりいる। বাস্তবে একেবারে ১০০% শুধু সেটিই নয়; বক্তার চোখে অস্বাভাবিক বেশি। নিজের নিরপেক্ষ routine বললে negative tone অনিচ্ছায় আসতে পারে।": "Nばかり, Vてばかりいる. Sa aktuwal ay hindi talagang 100% iyon lang; sa mata ng nagsasalita ay abnormal na marami. Kung sasabihin mo ang sarili mong neutral routine, maaaring hindi sinasadyang magkaroon ng negative tone.", "～だけ শুধু সীমা জানায়; ～ばかり criticism/একপেশে repetition দিতে পারে। ～たばかり “এইমাত্র”—সময়, এই rule নয়।": "Ipinapahayag lang ng ～だけ ang hangganan; ang ～ばかり ay maaaring magbigay ng criticism/panig na repetition. Ang ～たばかり ay \"katatapos lang\" — oras, hindi ang rule na ito.", "একটি দাঁড়িপাল্লার সব ওজন এক পাশে—একই কাজ ばかり করায় balance নষ্ট।": "Lahat ng bigat ng isang timbangan ay nasa isang panig — nasira ang balance dahil sa paggawa ng parehong bagay nang ばかり.", "কেউ পড়াশোনা না করে শুধু মোবাইল দেখে—てばかりいる দিয়ে বলো।": "May isang taong hindi nag-aaral at puro cellphone lang ang tinitingnan — sabihin ito gamit ang てばかりいる.", "বাস্তব জিনিস A-কে পরিচিত ছবি B-এর সঙ্গে তুলনা করে action/quality বোঝায়: “B-এর মতো করে/যেন B।”": "Ipinapaliwanag nito ang action/quality sa pamamagitan ng paghahambing ng tunay na bagay na A sa pamilyar na larawang B: \"sa paraang tulad ng B / na parang B.\"", "Nのように + V/A; Nのような + N। এটি intentional example-ও হতে পারে, poetic metaphor-ও হতে পারে।": "Nのように + V/A; Nのような + N. Maaari itong intentional example, maaari rin itong poetic metaphor.", "～みたいに casual; ～ように neutral/formal; ～かのように “বাস্তবে নয় কিন্তু যেন সত্যিই” আরও নাটকীয়।": "～みたいに ay casual; ～ように ay neutral/formal; ～かのように ay mas dramatiko — \"hindi naman talaga, ngunit parang totoo.\"", "একটি transparent ছবি অন্য ছবির ওপর বসেছে—দুইটি পুরো এক নয়, কিন্তু দেখতে একইরকম।": "Isang transparent na larawan ang nakapatong sa isa pang larawan — hindi ganap na iisa ang dalawa, ngunit magkamukha.", "“জাপানির মতো স্বাভাবিকভাবে কথা বলতে চাই”—ように ব্যবহার করো।": "\"Gusto kong makapagsalita nang natural tulad ng isang Japanese\" — gamitin ang ように.", "প্রথম item-টি obvious/expected; তার সঙ্গে আরও surprising item যোগ করে: “A তো অবশ্যই, B-ও।”": "Ang unang item ay obvious/expected; idinaragdag dito ang isa pang mas surprising na item: \"Ang A ay siyempre, at ang B rin.\"", "Aはもちろん、Bも। B সাধারণত A-এর চেয়ে কম প্রত্যাশিত বা scope-এ অতিরিক্ত। শুধু দুইটি সমান list করলে と/も যথেষ্ট।": "Aはもちろん、Bも. Ang B ay karaniwang hindi gaanong inaasahan kaysa A o karagdagang saklaw. Kung maglilista lang ng dalawang pantay na bagay, sapat na ang と/も.", "～ばかりでなく～も formal “শুধু নয়”; ～はもちろん～も-তে A নিয়ে সন্দেহই নেই, focus B-র extension।": "Ang ～ばかりでなく～も ay formal na \"hindi lang\"; sa ～はもちろん～も ay walang pagdududa tungkol sa A, at ang focus ay ang extension ng B.", "A-তে আগে থেকেই ✓ আছে; もちろん বলে B-তেও নতুন ✓ যোগ করো।": "May ✓ na ang A mula pa noon; gamit ang もちろん, magdagdag ng bagong ✓ sa B rin.", "এই সাইটে grammar তো আছেই, vocabulary-ও আছে—বাক্য বানাও।": "Sa site na ito, may grammar na nga, may vocabulary pa — bumuo ng pangungusap.", "A-কে reference point বানিয়ে B তার সমান মাত্রায় পৌঁছায় না: “B, A-এর মতো এতটা… নয়।”": "Ginagawa nitong reference point ang A, at hindi umaabot ang B sa parehong antas nito: \"Ang B ay hindi kasing… ng A.\"", "Aほど Bは～ない। Negative predicate comparison-এর অপরিহার্য অংশ; A “সবচেয়ে” বলা হচ্ছে না, শুধু B-এর upper benchmark।": "Aほど Bは～ない. Mahalagang bahagi ito ng negative predicate comparison; hindi sinasabing ang A ang \"pinaka\", kundi ito lang ang upper benchmark ng B.", "Rule 111-এর Aほど～はない = A-এর মতো আর কিছু নেই (superlative)। এখানে B স্পষ্ট এবং B কম।": "Ang Aほど～はない sa Rule 111 = walang ibang tulad ng A (superlative). Dito ay malinaw ang B at mas mababa ang B.", "A হলো উঁচু দাগ; B-এর রেখা সেই ほど দাগ পর্যন্ত পৌঁছাতে পারেনি।": "Ang A ay mataas na marka; hindi umabot ang linya ng B sa markang ほど na iyon.", "আজ গতকালের মতো ঠান্ডা নয়—ほど…ない দিয়ে বলো।": "Hindi kasinglamig ngayon ng kahapon — sabihin ito gamit ang ほど…ない.", "একটি জিনিস/কাজের জায়গায় অন্যটি substitute হয়, অথবা একটি সুবিধার বিনিময়ে অন্য অসুবিধা balance করে।": "Ang isa ay pumapalit sa lugar ng isang bagay/aksyon, o binabalanse ng isang benepisyo ang isa pang abala.", "Nのかわりに, plain form＋かわりに। Person replacement, action exchange, trade-off—context দেখে reading বেছে নাও।": "Nのかわりに, plain form＋かわりに. Pagpapalit ng tao, pagpapalitan ng aksyon, trade-off — piliin ang reading ayon sa context.", "～にかわって official replacement-এ বেশি; ～かわりに ব্যক্তিগত substitute ও “এর বদলে/বিনিময়ে” দুটোই।": "Ang ～にかわって ay mas para sa official replacement; ang ～かわりに ay kapwa personal substitute at \"bilang kapalit/kapalit\".", "দুই পাশের দোলনা: এক পাশ উঠলে অন্য পাশ নামে—かわりに হলো exchange।": "Seesaw na may dalawang panig: kapag tumaas ang isang panig, bumababa ang kabila — ang かわりに ay exchange.", "তুমি বন্ধুর shift-এর বদলে কাজ করবে—かわりに দিয়ে বলো।": "Magtatrabaho ka kapalit ng shift ng kaibigan mo — sabihin ito gamit ang かわりに.", "একটি কাজ না করেই অন্য কাজ সম্পন্ন হয়: “A না করে B।” ない-এর বদলে compact written connector ずに।": "Natatapos ang ibang aksyon nang hindi ginagawa ang isang aksyon: \"B nang hindi ginagawa ang A.\" Sa halip ng ない, ang compact written connector na ずに.", "Vない-এর ない বাদ + ずに; する→せずに বিশেষ রূপ। লিখিত/পরিপাটি, কথায় ないで বেশি common।": "Alisin ang ない ng Vない at idagdag ang ずに; ang する→せずに ay espesyal na anyo. Nakasulat/maayos ito; sa pananalita, mas common ang ないで.", "～ないで ও ～ずに প্রায় একই; ～なくて cause/state হতে পারে, কিন্তু “না করে” action sequence-এ ずに স্পষ্ট।": "Halos pareho ang ～ないで at ～ずに; ang ～なくて ay maaaring cause/state, ngunit sa action sequence na \"nang hindi ginagawa\", malinaw ang ずに.", "ない মুছে ず লিখে পাশে に—একটি সরাসরি formula: 食べない→食べずに。": "Burahin ang ない, isulat ang ず, at ilagay ang に sa tabi nito — isang direktang formula: 食べない→食べずに.", "নাশতা না করে স্কুলে গিয়েছ—ずに দিয়ে বলো।": "Pumasok ka sa paaralan nang hindi nag-aalmusal — sabihin ito gamit ang ずに.", "একটি অবস্থা যেমন ছিল তেমনই রেখে পরের কাজ করা বা সময় কেটে যাওয়া: state frozen, action continues।": "Iniiwan ang isang kalagayan kung ano ito at ginagawa ang susunod na aksyon o lumilipas ang oras: state frozen, action continues.", "Vたまま = করে রাখা; Vないまま = না করেই সেই অবস্থা; Nのまま। Result intentional বা accidental—দুটোই হতে পারে।": "Vたまま = ginawa at iniwang ganoon; Vないまま = ang kalagayang hindi ginawa; Nのまま. Ang result ay maaaring intentional o accidental — parehong posible.", "～っぱなし-এ neglect/একটানা ভাব; ～まま নিরপেক্ষ unchanged state; ～ながら simultaneous action, state freeze নয়।": "Sa ～っぱなし ay may pakiramdam ng neglect/pagtuloy-tuloy; ang ～まま ay neutral unchanged state; ang ～ながら ay simultaneous action, hindi state freeze.", "ছবির PAUSE button—frame বদলায়নি, তাই まま।": "PAUSE button ng larawan — hindi nagbago ang frame, kaya まま.", "জুতা না খুলেই ঘরে ঢুকেছে—ないまま দিয়ে বলো।": "Pumasok siya sa bahay nang hindi hinuhubad ang sapatos — sabihin ito gamit ang ないまま.", "লিখিত নির্দেশ, report বা formal narration-এ ます বাদ দেওয়া stem কাজগুলোকে compactভাবে জোড়া দেয়।": "Sa nakasulat na tagubilin, report, o formal narration, iniuugnay nito nang compact ang mga aksyon gamit ang stem na inalisan ng ます.", "店を出て、駅へ向かった-এর formal লিখিত রূপ 店を出、… নয়; verb অনুযায়ী 連用形: 店を出て? সব verb শুধু stem দিয়ে যুক্ত করা natural নয়—প্রচলিত formal verbs-এ বেশি।": "Ang formal na nakasulat na anyo ng 店を出て、駅へ向かった ay hindi 店を出、…; ayon sa verb ay 連用形: 店を出て? Hindi natural na pagdugtungin ang lahat ng verb gamit lamang ang stem — mas madalas ito sa mga itinakdang formal verb.", "て-form দৈনন্দিন ও বহুমুখী; ます-stem connection concise written style, বিশেষত recipes/notices: 加え、混ぜます।": "Ang て-form ay pang-araw-araw at maraming gamit; ang ます-stem connection ay concise written style, lalo na sa mga recipe/notice: 加え、混ぜます.", "Recipe-এর জায়গা বাঁচাতে ます কেটে comma বসেছে—切り、入れ、混ぜる。": "Upang makatipid ng espasyo sa recipe, inalis ang ます at naglagay ng comma — 切り、入れ、混ぜる.", "“কাগজটি ভাঁজ করে, বাক্সে রাখুন” recipe style stem দিয়ে লেখো।": "\"Tupiin ang papel at ilagay ito sa kahon\" — isulat ito sa recipe style gamit ang stem.", "একটি চলমান মুহূর্ত/পরিস্থিতির ঠিক মধ্যে নতুন ব্যক্তি বা ঘটনা এসে ঢোকে। ところ হলো scene, へ／に হলো incoming arrow।": "Isang bagong tao o pangyayari ang pumapasok sa gitna mismo ng isang nagpapatuloy na sandali/sitwasyon. Ang ところ ay ang scene, at ang へ／に ay ang incoming arrow.", "Vているところへ, Vようとしているところに। নতুন ঘটনার আগমন অনেক সময় বাধা, সাহায্য বা coincidence তৈরি করে।": "Vているところへ, Vようとしているところに. Ang pagdating ng bagong pangyayari ay madalas lumilikha ng hadlang, tulong, o coincidence.", "～最中に মাঝের সর্বোচ্চ point; ～ところへ একটি scene-এ আগমন; ～たところ result discovery।": "Ang ～最中に ay ang pinakagitnang point; ang ～ところへ ay pagdating sa isang scene; ang ～たところ ay result discovery.", "নাটকের stage-এ scene চলছে; পাশের দরজা দিয়ে নতুন চরিত্র ঢুকল—ところへ।": "Sa entablado ng isang dula ay nagpapatuloy ang scene; pumasok ang bagong karakter sa pintuan sa gilid — ところへ.", "বের হতে যাচ্ছিলে, তখন বন্ধুর ফোন এলো—ところに দিয়ে বলো।": "Lalabas ka na sana nang tumawag ang kaibigan mo — sabihin ito gamit ang ところに.", "কাজটি শুরু থেকে শেষ সীমা পর্যন্ত সম্পূর্ণ করা, অথবা ক্ষমতার শেষ পর্যন্ত করা। 切る মানে action-এর রেখা কেটে শেষ।": "Tinatapos ang isang aksyon mula simula hanggang sa huling hangganan, o ginagawa ito hanggang sa dulo ng kakayahan. Ang 切る ay nangangahulugang pinutol at tinapos ang linya ng action.", "読み切る সম্পূর্ণ পড়ে শেষ; 疲れ切る পুরোপুরি ক্লান্ত। Potential 切れる/negative 切れない-এ “পুরোটা পারা/না পারা”।": "読み切る ay basahin nang buo hanggang matapos; 疲れ切る ay lubusang pagod. Sa potential na 切れる/negative na 切れない ay \"kaya/hindi kaya ang kabuuan\".", "～終わる শুধু শেষ হওয়ার fact; ～きる completion/effort-এর totality জোর দেয়। ～かけ মাঝপথে অসম্পূর্ণ।": "Ipinapakita lang ng ～終わる ang fact na natapos; binibigyang-diin ng ～きる ang totality ng completion/effort. Ang ～かけ ay hindi kumpleto, nasa kalagitnaan.", "Finish line-এ ribbon কেটে দিলে—切る = পুরো পথ শেষ।": "Pinutol ang ribbon sa finish line — 切る = tinapos ang buong daan.", "বইটি এক দিনে সম্পূর্ণ পড়ে শেষ করেছ—読み切った দিয়ে বলো।": "Natapos mong basahin nang buo ang libro sa loob ng isang araw — sabihin ito gamit ang 読み切った.", "কোনো ব্যক্তি/ঘটনার কারণে ভালো ফল হয়েছে—কারণটির প্রতি gratitude বা positive evaluation যোগ করে।": "Dahil sa isang tao/pangyayari ay nagkaroon ng magandang resulta — idinaragdag nito ang gratitude o positive evaluation sa sanhi.", "Nのおかげで, plain form＋おかげで। Irony-তে খারাপ ফলের সঙ্গেও বলা যায়, কিন্তু tone স্পষ্ট না হলে ভুল বোঝাবে।": "Nのおかげで, plain form＋おかげで. Maaari rin itong sabihin sa irony para sa masamang resulta, ngunit kung hindi malinaw ang tone ay maaaring maunawaan nang mali.", "কারণের ওপর একটি “ধন্যবাদ” sticker—সেটিই おかげ。": "Isang \"salamat\" sticker sa ibabaw ng sanhi — iyon ang おかげ.", "শিক্ষকের সাহায্যে N3 বুঝতে পেরেছ—おかげで দিয়ে বলো।": "Dahil sa tulong ng guro ay naunawaan mo ang N3 — sabihin ito gamit ang おかげで.", "একটি সময়কাল শুরু থেকে শেষ পর্যন্ত বিস্তৃত: “পুরো N জুড়ে।” 通じて সময়ের tunnel-এর প্রতিটি অংশ cover করে।": "Isang panahon na umaabot mula simula hanggang wakas: \"sa buong N.\" Sinasaklaw ng 通じて ang bawat bahagi ng tunnel ng oras.", "一年を通じて／四季を通じて। সব মুহূর্তে একটানা হতে পারে, অথবা period-এর বিভিন্ন সময়ে বারবার—context নির্ধারণ করে।": "一年を通じて／四季を通じて. Maaari itong tuluy-tuloy sa bawat sandali, o paulit-ulit sa iba't ibang oras ng period — ang context ang magpapasya.", "～間ずっと strict continuous; ～を通じて entire span-এর general coverage। Rule 26 একই form-এ medium/intermediary অর্থ দেয়।": "Ang ～間ずっと ay strict continuous; ang ～を通じて ay general coverage ng entire span. Ang Rule 26 ay nagbibigay ng medium/intermediary na kahulugan sa parehong form.", "ক্যালেন্ডারের January থেকে December পর্যন্ত এক লম্বা highlight—を通じて。": "Isang mahabang highlight mula January hanggang December sa kalendaryo — を通じて.", "জাপানে সারা বছর বৃষ্টি হয় না—一年を通じて দিয়ে একটি সত্য বাক্য বলো।": "Hindi umuulan sa Japan sa buong taon — sabihin ang isang totoong pangungusap gamit ang 一年を通じて.", "Negative question form হলেও এখানে invitation নয়; বক্তা নিজের মতের সঙ্গে শ্রোতার agreement চাইছে: “এমন নয় কি?”": "Kahit negative question form ito, hindi ito invitation dito; hinahanap ng nagsasalita ang agreement ng listener sa sarili niyang opinyon: \"Hindi ba ganito?\"", "Context ও intonation জরুরি। 行きませんか invitation হতে পারে; 便利ではありませんか evaluation confirmation।": "Mahalaga ang context at intonation. Ang 行きませんか ay maaaring invitation; ang 便利ではありませんか ay evaluation confirmation.", "বাক্যের শেষে একটি ছোট “তাই না?” hook—ませんか listener-এর সম্মতি টেনে আনে।": "Isang maliit na kawit na \"hindi ba?\" sa dulo ng pangungusap — hinihila ng ませんか ang pagsang-ayon ng listener.", "“এই পদ্ধতিটি বেশি সহজ নয় কি?”—agreement question বানাও।": "\"Hindi ba mas madali ang paraang ito?\" — bumuo ng agreement question.", "একটি শব্দ/topic শুনলে সঙ্গে সঙ্গে যে representative image বা association মনে আসে সেটি বলে।": "Kapag narinig ang isang salita/topic, sinasabi nito ang representative image o association na agad pumapasok sa isip.", "Nというと, Nといえば। Topic define করা নয়; mental association খুলে দেওয়া। পরের কথা personal/common association হতে পারে।": "Nというと, Nといえば. Hindi nito binibigyang-kahulugan ang topic; binubuksan nito ang mental association. Ang susunod na sasabihin ay maaaring personal/common association.", "～について topic নিয়ে আলোচনা; ～というと “বললে মনে পড়ে”; ～というのは definition।": "Ang ～について ay pagtalakay tungkol sa topic; ang ～というと ay \"kapag sinabi, naaalala\"; ang ～というのは ay definition.", "শব্দটি বলতেই মাথায় light bulb জ্বলে উঠল—Nというと → প্রথম association।": "Pagkasabi pa lang ng salita ay umilaw ang light bulb sa ulo — Nというと → unang association.", "“জাপান বললে ফুজি পাহাড় মনে পড়ে”—というと দিয়ে বলো।": "\"Kapag sinabing Japan, naaalala ko ang Bundok Fuji\" — sabihin ito gamit ang というと.", "নৈতিকতা, দায়িত্ব বা সাধারণ মানদণ্ড থেকে “করা উচিত/উচিত নয়” বলে শক্ত judgement দেয়।": "Mula sa moralidad, responsibilidad, o karaniwang pamantayan, nagbibigay ito ng matibay na judgement na \"dapat gawin/hindi dapat gawin\".", "V辞書形＋べきだ; するべき／すべき দুটোই। ব্যক্তিগত ছোট পছন্দে ব্যবহার করলে অতিরিক্ত কর্তৃত্বপূর্ণ শোনাতে পারে।": "V辞書形＋べきだ; parehong するべき／すべき. Kung gagamitin sa maliit na personal na kagustuhan, maaaring makarinig na masyadong awtoritaryan.", "～たほうがいい নরম personal advice; ～べきだ strong principle/duty; ～なければならない বাস্তব বাধ্যতা।": "Ang ～たほうがいい ay malambot na personal advice; ang ～べきだ ay strong principle/duty; ang ～なければならない ay aktuwal na obligasyon.", "আইনের বইয়ের পাশে “SHOULD” সিল—べき。": "Selyong \"SHOULD\" sa tabi ng aklat ng batas — べき.", "কর্মস্থলে সময়মতো আসা উচিত—べきだ দিয়ে বলো।": "Dapat kang dumating sa trabaho sa tamang oras — sabihin ito gamit ang べきだ.", "একই বিষয় কার viewpoint/মূল্যবোধে কেমন, তা বলে: “N-এর কাছে/দৃষ্টিতে।” N হলো evaluator, benefit receiver নয় সবসময়।": "Sinasabi nito kung ano ang isang bagay mula sa viewpoint/halaga ng isang tao: \"para sa N / sa pananaw ni N.\" Ang N ang evaluator, hindi palaging benefit receiver.", "私にとって大切だ; 学生にとって難しい। Action target নয়, judgement-এর reference person/group।": "私にとって大切だ; 学生にとって難しい. Hindi ito action target, kundi ang reference person/group ng judgement.", "～のために = কার জন্য কাজ; ～に対して = কার প্রতি action; ～にとって = কার দৃষ্টিতে evaluation।": "～のために = aksyon para kanino; ～に対して = aksyon tungo kanino; ～にとって = evaluation sa pananaw nino.", "একই বস্তু তিনজন তিন রঙের চশমায় দেখছে—প্রতিটি চশমা にとって।": "Tinitingnan ng tatlong tao ang iisang bagay gamit ang tatlong salaming may iba't ibang kulay — bawat salamin ay にとって.", "তোমার কাছে পরিবার কত গুরুত্বপূর্ণ—私にとって দিয়ে বলো।": "Gaano kahalaga ang pamilya para sa iyo — sabihin ito gamit ang 私にとって.", "একটি মাত্রা বাড়া/কমার সঙ্গে আরেকটি মাত্রাও proportionalভাবে বদলায়: “যত A, তত B।”": "Isang antas ang tumataas/bumababa at kasabay nito ay nagbabago rin nang proportional ang isa pang antas: \"habang mas A, mas B.\"", "VばVるほど; いAければいAほど; なAならなAなほど। একই predicate পুনরাবৃত্তি formula-এর signal।": "VばVるほど; いAければいAほど; なAならなAなほど. Ang pag-uulit ng parehong predicate ang signal ng formula.", "～につれてও parallel change, কিন্তু natural progression-এ; ～ば～ほど condition-like proportional relationship।": "Nagpapakita rin ang ～につれて ng parallel change, ngunit sa natural progression; ang ～ば～ほど ay condition-like proportional relationship.", "দুইটি পাশাপাশি ওঠা সিঁড়ি—এক ধাপ A উঠলে এক ধাপ B ওঠে।": "Dalawang hagdanang magkatabing umaakyat — kapag umakyat ng isang hakbang ang A, umaakyat din ng isang hakbang ang B.", "যত জাপানি ব্যবহার করো, তত ভালো হও—話せば話すほど দিয়ে বলো।": "Habang mas ginagamit mo ang Japanese, mas gumagaling ka — sabihin ito gamit ang 話せば話すほど.", "N-কে ঘটনার objective/formal cause হিসেবে চিহ্নিত করে: “N-এর কারণে।” News, report, data explanation-এ বেশি।": "Minamarkahan nito ang N bilang objective/formal cause ng isang pangyayari: \"dahil sa N.\" Mas madalas ito sa news, report, at data explanation.", "事故による遅れ (N modification), 事故によって遅れた (sentence)। Human emotion-এর blame/gratitude নিজে যোগ করে না।": "事故による遅れ (N modification), 事故によって遅れた (sentence). Hindi ito mismo nagdaragdag ng blame/gratitude ng damdamin ng tao.", "～せいで blame; ～おかげで benefit; ～による neutral formal cause। Rule 21 একই form-এ means/method—result noun দেখে বোঝো।": "～せいで ay blame; ～おかげで ay benefit; ～による ay neutral formal cause. Ang Rule 21 ay means/method sa parehong form — unawain mula sa result noun.", "সংবাদপত্রের headline: 台風による被害—emotion নয়, cause label।": "Headline sa pahayagan: 台風による被害 — hindi emosyon, kundi cause label.", "ভারী বৃষ্টির কারণে ট্রেন বাতিল—による ব্যবহার করে noun phrase বানাও।": "Nakansela ang tren dahil sa malakas na ulan — bumuo ng noun phrase gamit ang による.", "A-তেই সীমাবদ্ধ নয়; scope B পর্যন্ত বাড়ে: “শুধু A নয়, B-ও।”": "Hindi limitado sa A lamang; lumalawak ang scope hanggang B: \"hindi lang A, kundi B rin.\"", "Plain form/N＋ばかりでなく、Bも。লিখিত/পরিপাটি; pair-এর দুই অংশ grammaticalভাবে parallel রাখলে পরিষ্কার হয়।": "Plain form/N＋ばかりでなく、Bも。Nakasulat/pormal; mas malinaw kung mananatiling gramatikal na magkapareho ang dalawang bahagi ng pares.", "～だけでなく সাধারণ; ～ばかりでなく formal; ～はもちろん-এ A obvious এবং B surprising।": "～だけでなく karaniwan; ～ばかりでなく pormal; sa ～はもちろん, halata ang A at nakakagulat ang B.", "A-র চারপাশের fence ভেঙে B-তেও জায়গা বাড়ল—ばかりでなく।": "Nabuwag ang bakod sa paligid ng A at lumawak ang espasyo hanggang sa B — ばかりでなく.", "এই কাজ শুধু কঠিন নয়, বিপজ্জনকও—ばかりでなく দিয়ে বলো।": "Ang trabahong ito ay hindi lang mahirap, mapanganib din — sabihin gamit ang ばかりでなく.", "A প্রতিবার ঘটলেই B নিয়মিত/স্বাভাবিকভাবে পুনরায় ঘটে। একটি event যেন B-এর repeat button।": "Tuwing nangyayari ang A, regular/natural na nauulit ang B. Para bang isang event ang repeat button ng B.", "Vるたびに, Nのたびに। B প্রতিবার একই exact result না হলেও recurring reaction/habit হয়। একবারের ঘটনা নয়।": "Vるたびに, Nのたびに. Kahit hindi eksaktong pareho ang resulta ng B sa bawat pagkakataon, ito ay paulit-ulit na reaksyon/ugali. Hindi ito minsanang pangyayari.", "～と automatic result; ～たびに repeated occasion + response; ～ごとに fixed interval/প্রতি unit।": "～と awtomatikong resulta; ～たびに paulit-ulit na okasyon + tugon; ～ごとに nakatakdang agwat/bawat unit.", "দরজার ঘণ্টা প্রতিবার চাপলেই একই আলো জ্বলে—AたびにB।": "Tuwing pinipindot ang doorbell, iisang ilaw ang umiilaw — AたびにB.", "দেশের কথা মনে পড়লেই পরিবারকে ফোন দাও—たびに দিয়ে বলো।": "Tuwing naaalala mo ang iyong bansa, tumatawag ka sa pamilya mo — sabihin gamit ang たびに.", "জানা তথ্য, নিয়ম বা যুক্তি মিলিয়ে expected conclusion: “হওয়ার কথা/নিশ্চয়ই।” শুধু ইচ্ছা নয়; reasoning আছে।": "Pinagsasama ang alam na impormasyon, tuntunin o lohika para makuha ang inaasahang konklusyon: “dapat mangyari/sigurado.” Hindi lang ito kagustuhan; may pangangatwiran.", "Plain form＋はずだ; Nのはず, なAなはず। はずだった expected ছিল কিন্তু হয়নি; はずがない logical impossibility।": "Plain form＋はずだ; Nのはず, なAなはず. Ang はずだった ay inaasahan pero hindi nangyari; ang はずがない ay lohikal na imposible.", "～だろう সাধারণ অনুমান; ～はず evidence-based expectation; ～に違いない আরও শক্ত inference; ～わけがない strong impossibility।": "～だろう karaniwang hula; ～はず inaasahan batay sa ebidensya; ～に違いない mas malakas na hinuha; ～わけがない matinding imposible.", "তিনটি clue যোগ করে puzzle-এর expected answer বের হলো—সেই answer はず。": "Pinagsama ang tatlong clue at lumabas ang inaasahang sagot sa puzzle — ang sagot na iyon ay はず.", "সে সকাল ৮টায় বের হয়েছে, তাই এখন পৌঁছে যাওয়ার কথা—はずだ দিয়ে বলো।": "Umalis siya ng 8:00 ng umaga, kaya dapat ay nakarating na siya ngayon — sabihin gamit ang はずだ.", "と-condition-কে です দিয়ে খুব ভদ্র customer-service style-এ আনে: “যদি এমন হয়, তাহলে…”।": "Ginagawang napakagalang ng です ang と-condition sa estilo ng customer service: “kung ganito ang mangyari, kung gayon…”", "N/なA＋ですと; V/いA plain＋と। দোকান, ফোন, service explanation-এ natural। Casual কথায় だと／なら বেশি।": "N/なA＋ですと; V/いA plain＋と. Natural sa tindahan, telepono, paliwanag ng serbisyo. Sa kaswal na usapan, mas madalas ang だと／なら.", "～なら advice-এর context; ～ですと polite automatic/result condition; ～ましたら business-polite conditional।": "～なら konteksto ng payo; ～ですと magalang na awtomatiko/resultang kondisyon; ～ましたら kondisyonal na magalang sa negosyo.", "দোকানের কাউন্টারে condition-কে uniform পরিয়ে দিল—だと → ですと।": "Sa counter ng tindahan, pinagsuot ng uniporme ang kondisyon — だと → ですと.", "“এই size হলে দাম ৩,০০০ yen”—service speech-এ ですと ব্যবহার করো।": "“Kung ganitong size, 3,000 yen ang presyo” — gamitin ang ですと sa pananalita ng serbisyo.", "দেখা লক্ষণ বা চলমান অবস্থা যদি সত্যিই সেই পর্যায়ে পৌঁছায়—তাহলে পরের judgement/action। よう “এমন অবস্থা”কে condition বানায়।": "Kung ang nakikitang senyales o kasalukuyang kalagayan ay tunay na umabot sa yugtong iyon — kung gayon ang susunod na paghatol/aksyon. Ginagawang kondisyon ng よう ang “ganitong kalagayan.”", "V/plain＋ようなら। Direct fact নয়; পরিস্থিতি পর্যবেক্ষণ করে conditional response। Often warning/advice: 続くようなら病院へ。": "V/plain＋ようなら. Hindi direktang katotohanan; kondisyonal na tugon matapos obserbahan ang sitwasyon. Madalas babala/payo: 続くようなら病院へ。", "～なら সাধারণ premise; ～ようなら “যদি লক্ষণ দেখে মনে হয় এমন চলছে/ঘটবে”। ～そうなら surface appearance-এর সরাসরি condition।": "～なら karaniwang premise; ～ようなら “kung sa mga senyales ay mukhang ganito ang nangyayari/mangyayari”. Ang ～そうなら ay direktang kondisyon ng nakikitang anyo.", "Dashboard-এর warning light জ্বললে action নাও—লক্ষণ → ようなら → response।": "Kapag umilaw ang warning light sa dashboard, kumilos — senyales → ようなら → tugon.", "জ্বর চলতে থাকলে হাসপাতালে যেতে বলো—ようなら দিয়ে বলো।": "Sabihing pumunta sa ospital kung magpatuloy ang lagnat — sabihin gamit ang ようなら.", "অতীতের কোনো point থেকে পরিবর্তন/অবস্থা এগিয়ে এখন দৃশ্যমান হয়েছে। くる সময়রেখায় NOW-এর দিকে আসা arrow।": "Mula sa isang punto sa nakaraan, ang pagbabago/kalagayan ay umusad at nakikita na ngayon. Ang くる ay arrow na papalapit sa NGAYON sa timeline.", "暖かくなってきた, 分かってきた, 人が増えてきた। পরিবর্তনের শুরু অতীতে, বর্তমান ফল/প্রবণতা গুরুত্বপূর্ণ।": "暖かくなってきた, 分かってきた, 人が増えてきた. Nagsimula ang pagbabago sa nakaraan; mahalaga ang kasalukuyang resulta/tendensya.", "～てきた = past→now; ～ていく = now→future। Physical 来る অর্থ না ধরলেও হবে।": "～てきた = nakaraan→ngayon; ～ていく = ngayon→hinaharap. Hindi kailangang kunin ang pisikal na kahulugan ng 来る.", "PAST ——→ NOW; arrow তোমার দিকে “এসেছে”—তাই くる।": "PAST ——→ NOW; ang arrow ay “dumating” patungo sa iyo — kaya くる.", "জাপানি ধীরে ধীরে বুঝতে শুরু করেছ—分かってきた দিয়ে বলো।": "Unti-unti mo nang nauunawaan ang Japanese — sabihin gamit ang 分かってきた.", "নিজের অসুবিধাজনক পরিস্থিতি ব্যাখ্যা করে excuse/reason নরমভাবে দেয়: “আসলে… বলে।”": "Ipinapaliwanag ang sariling hindi maginhawang sitwasyon at mahinahong nagbibigay ng palusot/dahilan: “kasi talaga…”", "Plain form＋ものですから; N/なA＋なものですから। নিজের দায় এড়ানোর tone হতে পারে, তাই formal apology-তে কারণের সঙ্গে ক্ষমাও দাও।": "Plain form＋ものですから; N/なA＋なものですから. Maaaring magtunog na iniiwasan mo ang responsibilidad, kaya sa pormal na paghingi ng paumanhin, samahan ng paghingi ng tawad ang dahilan.", "ক্ষমা চাইতে গিয়ে কারণের চারপাশে soft cushion—ものですから।": "Isang malambot na unan sa paligid ng dahilan habang humihingi ng paumanhin — ものですから.", "ট্রেন দেরি করায় তুমি late—ものですから দিয়ে বিনয়ের সঙ্গে বোঝাও।": "Late ka dahil naantala ang tren — ipaliwanag nang magalang gamit ang ものですから.", "একটি বা কয়েকটি representative example casualভাবে তোলে: “যেমন N/ইত্যাদি।” কখনো topic-কে হালকা বা ছোট করে দেখায়।": "Nagbabanggit nang kaswal ng isa o ilang halimbawang kinatawan: “tulad ng N/at iba pa.” Minsan pinapaliit o pinapagaan nito ang paksa.", "Nなんか। Tone friendly example, surprise, disdain—সব হতে পারে; ব্যক্তি সম্পর্কে ব্যবহার করলে অসম্মান শোনাতে পারে।": "Nなんか. Maaaring friendly na halimbawa, gulat, o paghamak ang tono — lahat posible; kung gagamitin tungkol sa tao, maaaring magtunog na walang galang.", "～など neutral/formal examples; ～なんか casual; Rule 90-এ একই form contempt/humility বিশেষভাবে জোরালো।": "～など neutral/pormal na mga halimbawa; ～なんか kaswal; sa Rule 90, ang parehong anyo ay lalo pang binibigyang-diin ang paghamak/pagpapakumbaba.", "Formal “など” casual পোশাক পরে “なんか” হয়েছে।": "Ang pormal na “など” ay nagsuot ng kaswal na damit at naging “なんか”.", "ছুটির দিনে সিনেমা ইত্যাদি দেখতে চাও—なんか দিয়ে casual বাক্য বলো।": "Sa araw ng pahinga, gusto mong manood ng sine at iba pa — gumawa ng kaswal na pangungusap gamit ang なんか.", "নিজের মত/প্রস্তাবকে absolute না করে “হয়তো এমন মনে হয়” বলে নরম ও বিনয়ী করে।": "Pinapalambot at ginagawang magalang ang sariling opinyon/mungkahi sa pamamagitan ng hindi pagiging absolute: “parang sa tingin ko siguro ganito.”", "Plain form＋かと思います। Business বা teacher-facing কথায় disagreement/estimate soft করতে উপকারী। নিজের নিশ্চিত fact-ও অযথা অস্পষ্ট করে ফেলো না।": "Plain form＋かと思います. Kapaki-pakinabang para palambutin ang hindi pagkakasundo/pagtantya sa negosyo o sa pakikipag-usap sa guro. Huwag ding gawing malabo nang hindi kailangan ang sarili mong tiyak na katotohanan.", "～と思います সাধারণ মত; ～かと思います আরও tentative/polite; ～だろうと思います probability-এর content স্পষ্ট করে।": "～と思います karaniwang opinyon; ～かと思います mas nag-aalangan/magalang; nililinaw ng ～だろうと思います ang nilalaman ng probabilidad.", "মতের ধারালো কোণের ওপর ছোট か cushion বসেছে—শ্রোতার কাছে নরম পৌঁছায়।": "May maliit na か na unan sa matalim na sulok ng opinyon — malambot itong dumarating sa nakikinig.", "“এই সময়টা সুবিধাজনক হবে বলে মনে করি”—かと思います দিয়ে বলো।": "“Sa tingin ko magiging maginhawa ang oras na ito” — sabihin gamit ang かと思います.", "A চলতে থাকাকালে সচেতন পরিকল্পনা ছাড়াই B ধীরে ধীরে পরিবর্তিত হয়। Focus হলো duration-এর ভেতরের natural change।": "Habang patuloy ang A, unti-unting nagbabago ang B nang walang malay na plano. Ang pokus ay ang natural na pagbabago sa loob ng tagal.", "Vているうちに B। B accidental learning, familiarity, feeling change ইত্যাদি। Planned কাজ “সময় থাকতে করি” হলে Rule 81।": "Vているうちに B. Ang B ay aksidenteng pagkatuto, pagkasasanay, pagbabago ng pakiramdam, atbp. Kung planadong gawain na “gawin habang may oras pa,” Rule 81 iyon.", "এই rule: 話しているうちに慣れた (চলতে চলতে বদল); Rule 81: 忘れないうちに書く (অবস্থা বদলানোর আগে করি)।": "Ang rule na ito: 話しているうちに慣れた (nagbago habang nagpapatuloy); Rule 81: 忘れないうちに書く (gawin bago magbago ang kalagayan).", "একটি নদীর ভেতর চলতে চলতে পাথর মসৃণ হলো—うちに-এর natural change।": "Habang dumadaloy sa loob ng isang ilog, naging makinis ang bato — ang natural na pagbabago ng うちに.", "জাপানিদের সঙ্গে কথা বলতে বলতে ভয় কমেছে—うちに দিয়ে বলো।": "Habang nakikipag-usap sa mga Japanese, nabawasan ang takot mo — sabihin gamit ang うちに.", "কাজটি বক্তার অনুভূতিতে খুব অল্প আগে শেষ হয়েছে: “এইমাত্র/সবে।” ঘড়ির exact মিনিট নয়, psychological recency।": "Katatapos lang ng gawain, sa pakiramdam ng nagsasalita napakalapit pa lang: “kagagaling lang/kakatapos lang.” Hindi eksaktong minuto sa orasan, kundi psychological recency.", "Vたばかり। কয়েক মাসও context-এ “সবে” হতে পারে। Objective ところ-এর তুলনায় speaker judgement বেশি।": "Vたばかり. Kahit ilang buwan ay maaaring maging “kaka- lang” depende sa konteksto. Mas may paghatol ng nagsasalita kumpara sa objective na ところ.", "Vたところ = ঠিক এখন action complete/ফল; Vたばかり = speaker মনে করে অল্প আগে; ばかり criticism নয়।": "Vたところ = eksaktong ngayon natapos ang aksyon/resulta; Vたばかり = sa tingin ng nagsasalita, kalipas lang nang kaunti; ang ばかり ay hindi kritisismo.", "ঘটনার ওপর এখনো “NEW” sticker লেগে আছে—たばかり。": "May nakadikit pang “NEW” na sticker sa pangyayari — たばかり.", "তুমি জাপানে সবে এসেছ—来たばかり দিয়ে বলো।": "Kakarating mo lang sa Japan — sabihin gamit ang 来たばかり.", "“এটা করলেই তো ভালো”—অন্যের action নিয়ে wish, complaint বা চাপযুক্ত পরামর্শ। のに unmet expectation যোগ করে।": "“Mas mabuti kung gagawin niya ito” — isang hiling, reklamo o mapilit na payo tungkol sa aksyon ng iba. Nagdaragdag ang のに ng hindi natupad na inaasahan.", "Subject অন্য ব্যক্তি হলে criticism শোনাতে পারে। নিজের জন্যও wish হতে পারে: もっと時間があればいいのに। সম্পর্ক/টোন বিবেচনা করো।": "Kung ibang tao ang subject, maaaring magtunog na kritisismo. Maaari rin itong hiling para sa sarili: もっと時間があればいいのに. Isaalang-alang ang relasyon/tono.", "～ばいい neutral solution; ～たほうがいい advice; ～ばいいのに emotional “করলেই তো!”।": "～ばいい neutral na solusyon; ～たほうがいい payo; ～ばいいのに emosyonal na “kung gagawin lang sana!”", "সমাধানের দরজা খোলা, কিন্তু মানুষ ঢুকছে না—তুমি বলছ “ঢুকলেই তো ভালো!”": "Bukas ang pinto ng solusyon, pero hindi pumapasok ang tao — sinasabi mo, “pumasok ka na lang sana!”", "বন্ধুকে বলো, না বুঝলে শিক্ষককে জিজ্ঞেস করলেই তো ভালো—ばいいのに।": "Sabihin sa kaibigan mo na mas mabuti kung magtatanong siya sa guro kung hindi niya maintindihan — ばいいのに.", "শ্রোতাকে তোমার benefit-এর জন্য action করতে অনুরোধ: “আপনি কি আমার জন্য… করতে পারবেন?” もらう beneficiary viewpoint রাখে।": "Humihiling sa nakikinig na gumawa ng aksyon para sa iyong kapakinabangan: “Puwede mo bang… para sa akin?” Pinapanatili ng もらう ang pananaw ng nakikinabang.", "Vて＋もらってもいいですか। পরিচিত/সেবা পরিস্থিতিতে polite; আরও formal হলে ～ていただけますか／いただけないでしょうか।": "Vて＋もらってもいいですか. Magalang sa kakilala/sitwasyon ng serbisyo; kung mas pormal, ～ていただけますか／いただけないでしょうか.", "～てもいいですか = আমি করতে পারি?; ～てもらってもいいですか = আপনি আমার জন্য করবেন? Subject উল্টে যায়।": "～てもいいですか = puwede ba akong gumawa?; ～てもらってもいいですか = gagawin mo ba para sa akin? Nagpapalitan ang subject.", "Action giftটি আমি “পাব”—তাই もらう।": "Ang “regalo” ng aksyon ay “matatanggap” ko — kaya もらう.", "কাউকে একটি ছবি তুলতে অনুরোধ করো—撮ってもらってもいいですか।": "Hilingin sa isang tao na kunan ka ng larawan — 撮ってもらってもいいですか.", "উচ্চ মর্যাদার কারও কাছ থেকে সেবা/কাজ পাওয়া humble viewpoint-এ জানায়। ご/お action-কে সম্মানিত করে, いただく নিজেকে নিচু করে।": "Sinasabi nang may pagpapakumbaba na nakatanggap ka ng serbisyo/gawa mula sa isang taong may mataas na katayuan. Ang ご/お ay nagbibigay-galang sa aksyon, ang いただく ay nagpapababa sa sarili.", "お＋和語Vます stem＋いただく; ご＋漢語N＋いただく। সব verb mechanicalভাবে নয়—প্রচলিত keigo form ব্যবহার করো।": "お＋和語Vます stem＋いただく; ご＋漢語N＋いただく. Hindi lahat ng verb ay mekanikal — gamitin ang karaniwang anyong keigo.", "উপরে সম্মানিত ব্যক্তি, নিচে দুই হাতে সেবা গ্রহণ করছি—いただく-এর ছবিই “নিচ থেকে পাওয়া।”": "Sa itaas ang taong iginagalang, sa ibaba tinatanggap ko ang serbisyo gamit ang dalawang kamay — ang larawan ng いただく ay “pagtanggap mula sa ibaba.”", "শিক্ষক তোমার CV দেখে দিয়েছেন—ご確認いただきました দিয়ে বলো।": "Tiningnan ng guro ang CV mo — sabihin gamit ang ご確認いただきました.", "～ていました-এর spoken polite contraction। Past continuous/habit/state একই থাকে; শুধু উচ্চারণে い বাদ।": "Spoken na magalang na contraction ng ～ていました. Nananatiling pareho ang past continuous/ugali/state; tinatanggal lang ang い sa pagbigkas.", "話していました→話してました। কথায় polite হলেও formal লিখিত text-এ পূর্ণ form ভালো। てた আরও casual।": "話していました→話してました. Kahit magalang sa pagsasalita, mas mabuti ang buong anyo sa pormal na nakasulat na teksto. Ang てた ay mas kaswal pa.", "てました = polite spoken; てた = casual spoken; ていました = পূর্ণ standard।": "てました = magalang na sinasalita; てた = kaswal na sinasalita; ていました = buong pamantayan.", "い শব্দটি দ্রুত কথায় train miss করেছে—ていました → てました।": "Naligaw ng tren sa mabilis na pagsasalita ang salitang い — ていました → てました.", "“গত রাতে দশটা পর্যন্ত কাজ করছিলাম”—てました দিয়ে spoken বাক্য বলো।": "“Nagtatrabaho ako hanggang alas-10 kagabi” — sabihin ang sinasalitang pangungusap gamit ang てました.", "「知っている」-এর humble বিশেষ রূপ, বিশেষ করে সম্মানিত কোনো ব্যক্তিকে চিনি/জানি বলতে। নিজের জানা কাজকে নিচু করে।": "Espesyal na humble na anyo ng 「知っている」, lalo na sa pagsasabing kilala/alam mo ang isang taong iginagalang. Ibinababa nito ang sariling kaalaman.", "Person-কে 知る: 存じ上げています। Fact/item-কে জানা: 存じています বেশি স্বাভাবিক। Negative: 存じ上げません。": "Pag-alam sa isang Person gamit ang 知る: 存じ上げています. Pag-alam sa Fact/item: mas natural ang 存じています. Negative: 存じ上げません.", "ご存じです = “আপনি জানেন” honorific; 存じています = “আমি জানি” humble; 存じ上げる person-knowledge-এ বিশেষ।": "ご存じです = “alam ninyo” honorific; 存じています = “alam ko” humble; ang 存じ上げる ay espesyal para sa kaalaman tungkol sa tao.", "上げる kanji দেখে ভুলে “নিজেকে ওপরে” ভাববে না—আমি সম্মানটি ওপরে তুলে দিচ্ছি, নিজে নিচে।": "Huwag magkamaling isipin na “itinataas ang sarili” dahil nakikita ang kanji na 上げる — itinataas ko ang galang pataas, ako mismo ay nasa ibaba.", "একজন সম্মানিত ব্যক্তিকে তুমি চেনো না—存じ上げません দিয়ে বলো।": "Hindi mo kilala ang isang taong iginagalang — sabihin gamit ang 存じ上げません.", "সম্মানিত ব্যক্তির চলমান action/state-কে お＋ます-stem＋です দিয়ে সংক্ষিপ্ত honorific বানায়।": "Ginagawang maikling honorific ang kasalukuyang aksyon/kalagayan ng isang taong iginagalang gamit ang お＋ます-stem＋です.", "先生はもうお帰りです。 সব verb নয়; single-mora stem বা unnatural combinations এড়িয়ে established form ব্যবহার করো।": "先生はもうお帰りです. Hindi lahat ng verb; iwasan ang single-mora stem o hindi natural na kombinasyon at gamitin ang nakasanayang anyo.", "Verb-এর সামনে お সম্মানের badge, শেষে です uniform—মাঝে ます-stem।": "Sa harap ng Verb ang お ay badge ng galang, sa dulo ang です ay uniporme — sa gitna ang ます-stem.", "ম্যানেজার এখন বাইরে গেছেন/অনুপস্থিত—お出かけです দিয়ে বলো।": "Wala/lumabas ngayon ang manager — sabihin gamit ang お出かけです.", "でしょうか সরাসরি প্রশ্নের ধার কমিয়ে অত্যন্ত ভদ্র inquiry/uncertainty বানায়।": "Binabawasan ng でしょうか ang talim ng direktang tanong at ginagawa itong napakagalang na pagtatanong/kawalang-katiyakan.", "疑問語＋でしょうか, plain＋のでしょうか। দোকান, interview, email-এ উপযুক্ত। তথ্য নিশ্চিত জেনেও ব্যবহার করলে দূরত্ব তৈরি হয়।": "疑問語＋でしょうか, plain＋のでしょうか. Angkop sa tindahan, interview, email. Kung gagamitin kahit tiyak mong alam ang impormasyon, lumilikha ito ng distansya.", "ですか সাধারণ polite; でしょうか softer/more formal; ませんか invitation/agreement হতে পারে।": "ですか karaniwang magalang; でしょうか mas malambot/mas pormal; ませんか maaaring imbitasyon/pagsang-ayon.", "প্রশ্নচিহ্নের চারপাশে তুলোর cushion—でしょうか।": "Isang unan ng bulak sa paligid ng tandang pananong — でしょうか.", "Interview-এ কাজ কখন শুরু হবে জানতে ভদ্রভাবে প্রশ্ন করো।": "Sa isang Interview, magalang na itanong kung kailan magsisimula ang trabaho.", "です／である／いる-এর honorific equivalent; সম্মানিত ব্যক্তির identity, state বা presence উঁচু করে বলে।": "Honorific na katumbas ng です／である／いる; sinasabi nang may pagtaas ang pagkakakilanlan, kalagayan o presensya ng isang taong iginagalang.", "N/なA＋でいらっしゃる। Person subject দরকার; নিজের বা বস্তু সম্পর্কে ব্যবহার করো না। Spoken polite: でいらっしゃいます。": "N/なA＋でいらっしゃる. Kailangan ng Person na subject; huwag gamitin tungkol sa sarili o sa bagay. Magalang na sinasalita: でいらっしゃいます.", "です neutral; でございます humble/polite service speech (বস্তুতেও); でいらっしゃる subject-honorific person।": "です neutral; でございます humble/magalang na pananalita ng serbisyo (para rin sa bagay); でいらっしゃる subject-honorific para sa tao.", "いらっしゃる মানে সম্মানিত ব্যক্তি “উপস্থিত”—で দিয়ে তাঁর state-এ যুক্ত।": "Ang ibig sabihin ng いらっしゃる ay ang taong iginagalang ay “naroroon” — ikinakabit ng で sa kanyang kalagayan.", "অতিথি একজন বিশ্ববিদ্যালয়ের শিক্ষক—先生でいらっしゃいます দিয়ে পরিচয় দাও।": "Ang panauhin ay isang guro sa unibersidad — ipakilala gamit ang 先生でいらっしゃいます.", "অনুমতি/পরিস্থিতির সুযোগ গ্রহণ করে বক্তা বিনয়ের সঙ্গে নিজে action করবে—humble business declaration।": "Sinasamantala ang pahintulot/pagkakataon ng sitwasyon, ang nagsasalita ay magalang na siya mismo ang gagawa ng aksyon — humble na deklarasyon sa negosyo.", "বাস্তব বা সামাজিকভাবে অনুমতি/benefit থাকার context চাই। নিজের সাধারণ কাজেও অতিরিক্ত ব্যবহার করলে “keigo overuse” শোনাতে পারে।": "Kailangan ng konteksto kung saan may aktuwal o panlipunang pahintulot/benepisyo. Kung sobra ang gamit kahit sa sariling karaniwang gawain, maaaring magtunog na “keigo overuse.”", "させてもらう neutral permission received; させていただく very polite/humble; いたします শুধু “করব” humble, causative permission নয়।": "させてもらう neutral na pahintulot na natanggap; させていただく napakagalang/humble; ang いたします ay “gagawin ko” lang na humble, hindi causative na pahintulot.", "দরজায় অনুমতি নিয়ে মাথা নত করে ঢুকছি—させて + いただきます।": "Sa pintuan, humihingi ng pahintulot, yumuyuko at pumapasok — させて + いただきます.", "Interview শুরু করার আগে “নিজের পরিচয় দিতে দিন” এই pattern-এ বলো।": "Bago magsimula ang Interview, sabihin sa pattern na ito ang “pakihintulutan akong ipakilala ang aking sarili.”", "A আগে সম্পন্ন হওয়া B-এর অপরিহার্য prerequisite: “A না করা পর্যন্ত B সম্ভব/অনুমোদিত নয়।”": "Ang A na natapos muna ay mahalagang prerequisite ng B: “hangga't hindi nagagawa ang A, hindi posible/pinahihintulutan ang B.”", "Vてからでなければ、Bない／できない। B সাধারণত negative/impossible; A শুধু chronological নয়, required gate।": "Vてからでなければ、Bない／できない. Karaniwang negative/imposible ang B; ang A ay hindi lang kronolohikal, ito ay kinakailangang gate.", "～てから তারপর; ～たあとで শুধু sequence; ～てからでなければ prerequisite ছাড়া B blocked।": "～てから pagkatapos; ～たあとで pagkakasunod lang; ～てからでなければ kung walang prerequisite, naka-block ang B.", "A হলো locked gate-এর key; key না ঘোরালে B-room খুলবে না।": "Ang A ay susi ng naka-lock na gate; kung hindi iikot ang susi, hindi bubukas ang B-room.", "পরিচয় যাচাই না হলে কার্ড ব্যবহার করা যাবে না—এই structure-এ বলো।": "Sabihin sa istrukturang ito na hindi magagamit ang card kung hindi pa nabeberipika ang pagkakakilanlan.", "বাস্তবে A নয়, কিন্তু আচরণ/দৃশ্য এতটাই A-এর মতো যেন সত্যিই A—dramatic or literary simile।": "Sa realidad hindi A, pero ang kilos/eksena ay sobrang katulad ng A na para bang tunay na A — dramatiko o pampanitikang paghahambing.", "Plain＋かのように; N/なA＋であるかのように। Writer জানে comparisonটি unreal/figurative।": "Plain＋かのように; N/なA＋であるかのように. Alam ng manunulat na hindi totoo/figurative ang paghahambing.", "～ように neutral resemblance; ～みたいに casual; ～かのように “যেন সত্যিই”—unreal gap ও নাটকীয়তা বেশি।": "～ように neutral na pagkakahawig; ～みたいに kaswal; ～かのように “para bang tunay talaga” — mas malaki ang unreal na agwat at dramatismo.", "থিয়েটারের অভিনেতা রাজা নয়, কিন্তু এমন অভিনয় করছে যেন সত্যিই রাজা—かのように।": "Ang aktor sa teatro ay hindi hari, pero umaarte siya na para bang tunay siyang hari — かのように.", "সে সবকিছু জানে এমনভাবে কথা বলে—知っているかのように দিয়ে বলো।": "Nagsasalita siya na para bang alam niya ang lahat — sabihin gamit ang 知っているかのように.", "বর্তমান সুবিধাজনক অবস্থা বদলে যাওয়ার আগে সেই window-এর ভেতর intentional action শেষ করা: “সময়/সুযোগ থাকতে।”": "Tapusin ang sinadyang aksyon sa loob ng window bago magbago ang kasalukuyang maginhawang kalagayan: “habang may oras/pagkakataon pa.”", "Vる／Vない／いA／なAな／Nの＋うちに। B বক্তার পরিকল্পিত কাজ। 夜にならないうちに帰る-এর মতো deadline feeling থাকে।": "Vる／Vない／いA／なAな／Nの＋うちに. Ang B ay planadong gawain ng nagsasalita. May pakiramdam ng deadline, tulad ng 夜にならないうちに帰る.", "Rule 68-এ A চলতে চলতে B অনিচ্ছায় বদলায়; এখানে A বদলানোর আগেই B সচেতনভাবে করি। ～間に শুধু সময়ের মধ্যে, change-before nuance কম।": "Sa Rule 68, habang nagpapatuloy ang A, nagbabago ang B nang hindi sinasadya; dito, sinasadya kong gawin ang B bago magbago ang A. Ang ～間に ay nasa loob lang ng panahon, mas mahina ang nuance na bago magbago.", "বরফ গলার আগে ice cream খেয়ে ফেলো—সুযোগের জানালা বন্ধ হওয়ার আগেই うちに।": "Kainin ang ice cream bago ito matunaw — うちに bago magsara ang bintana ng pagkakataon.", "ভুলে যাওয়ার আগে note লিখবে—忘れないうちに দিয়ে বলো।": "Magsusulat ka ng note bago mo makalimutan — sabihin gamit ang 忘れないうちに.", "পণ্য, বই, সেবা বা তথ্য কোন নির্দিষ্ট audience-এর প্রয়োজন অনুযায়ী তৈরি—target design বোঝায়।": "Ang produkto, aklat, serbisyo o impormasyon ay ginawa ayon sa pangangailangan ng isang partikular na audience — nagpapahiwatig ng target na disenyo.", "N向けのN／N向けに作る। “কার উপযোগী করে বানানো” গুরুত্বপূর্ণ; কেবল destination direction নয়।": "N向けのN／N向けに作る. Mahalaga ang “ginawa para maging angkop kanino”; hindi lang direksyon ng destinasyon.", "～向け = intended audience; ～向き = স্বভাবগতভাবে suitable। 子ども向けの本 বানানো হয়েছে শিশুদের জন্য; 子ども向き সহজে উপযোগী।": "～向け = nilalayong audience; ～向き = likas na angkop. Ang 子ども向けの本 ay ginawa para sa mga bata; ang 子ども向き ay madaling maging angkop.", "প্যাকেটের ওপর audience sticker: 「留学生向け」—কার দিকে design মুখ করা আছে।": "Sticker ng audience sa pakete: 「留学生向け」— kung kanino nakaharap ang disenyo.", "বিদেশি শিক্ষার্থীদের জন্য তৈরি একটি guide—向け ব্যবহার করে বলো।": "Isang guide na ginawa para sa mga dayuhang estudyante — sabihin gamit ang 向け.", "ব্যক্তি, দেশ, সময় বা পদ্ধতি বদলালে ফলও ভিন্ন হয়: “N ভেদে/অনুযায়ী।”": "Kung magbabago ang tao, bansa, oras o paraan, mag-iiba rin ang resulta: “ayon sa/nag-iiba depende sa N.”", "Nによって違う／変わる; Nによっては exception “কিছু N-এর ক্ষেত্রে”। Cause/method/agent অর্থ context অনুযায়ী আলাদা।": "Nによって違う／変わる; ang Nによっては ay eksepsyon na “sa kaso ng ilang N”. Ang kahulugang cause/method/agent ay nag-iiba ayon sa konteksto.", "人によって考えが違う = ভেদে; 雨によって中止 = কারণে; インターネットによって = মাধ্যমে। Predicate অর্থটি ঠিক করে।": "人によって考えが違う = depende sa; 雨によって中止 = dahil sa; インターネットによって = sa pamamagitan ng. Ang Predicate ang nagpapasya sa kahulugan.", "একই switch বিভিন্ন মানুষ চাপলে বিভিন্ন রঙ জ্বলে—Nによって difference।": "Iisang switch, pero kapag iba't ibang tao ang pumindot, iba't ibang kulay ang umiilaw — pagkakaiba ng Nによって.", "দোকানভেদে দাম আলাদা—店によって দিয়ে বলো।": "Nag-iiba ang presyo depende sa tindahan — sabihin gamit ang 店によって.", "একটি কাজের একেবারে মাঝের সবচেয়ে active point-এ অন্য ঘটনা ঘটে: “ঠিক A চলার মাঝখানে।”": "Sa pinakaaktibong punto sa gitna mismo ng isang gawain, may ibang pangyayaring nagaganap: “eksaktong nasa kalagitnaan ng A.”", "Vている最中に／Nの最中に। ছোট interruption বা unexpected event বেশি natural। শুরু/শেষের কাছে হলে 最中 nuance দুর্বল।": "Vている最中に／Nの最中に. Mas natural ang maliit na pagkaantala o hindi inaasahang pangyayari. Kung malapit sa simula/dulo, humihina ang nuance ng 最中.", "～間に broad duration; ～ところに specific phase; ～最中に peak middle এবং interruption।": "～間に malawak na tagal; ～ところに partikular na yugto; ～最中に rurok na gitna at pagkaantala.", "Movie progress bar-এর ঠিক ৫০%-এ phone বাজল—最中。": "Eksaktong sa 50% ng progress bar ng Movie, tumunog ang phone — 最中.", "খাওয়ার মাঝখানে manager ফোন করেছেন—最中に দিয়ে বলো।": "Sa kalagitnaan ng pagkain, tumawag ang manager — sabihin gamit ang 最中に.", "কাজ শুরু হয়েছে কিন্তু completion-এর আগে থেমে/অসম্পূর্ণ অবস্থায় আছে: “অর্ধেক করা/করতে যাচ্ছিল।”": "Nagsimula na ang gawain pero huminto/bago matapos at nananatiling hindi kumpleto: “kalahating nagawa/muntik nang gawin.”", "Vます stem＋かけ／かける／かけのN। physical অসম্পূর্ণ কাজ ও near-event দুটো: 読みかけの本, 死にかけた।": "Vます stem＋かけ／かける／かけのN. Parehong pisikal na hindi tapos na gawain at near-event: 読みかけの本, 死にかけた.", "～始める শুধু শুরু; ～かけ incomplete midpoint; ～きる full completion। তিনটি একটি progress bar-এর তিন জায়গা।": "～始める simula lang; ～かけ hindi kumpletong gitna; ～きる ganap na pagtatapos. Tatlong lugar sa iisang progress bar ang tatlo.", "Progress bar ৪০%-এ থেমে আছে—তার ওপর かけ label।": "Huminto ang Progress bar sa 40% — may かけ na label sa ibabaw nito.", "অর্ধেক পড়া বইটি টেবিলে আছে—読みかけの本 দিয়ে বলো।": "Ang kalahating nabasang aklat ay nasa mesa — sabihin gamit ang 読みかけの本.", "আবেগ/স্বতঃস্ফূর্ত তাগিদ এত শক্ত যে action না করে থাকা যায় না: “নিজেকে আটকাতে পারি না।”": "Napakalakas ng damdamin/kusang udyok na hindi mapigilan ang hindi paggawa ng aksyon: “hindi ko mapigilan ang sarili ko.”", "Vない-এর ない বাদ＋ずにはいられない; する→せずにはいられない। External duty নয়, inner impulse।": "Tinatanggal ang ない ng Vない＋ずにはいられない; する→せずにはいられない. Hindi panlabas na tungkulin, kundi panloob na udyok.", "～なければならない বাধ্যতা; ～ずにはいられない uncontrollable urge; ～てしょうがない action নয়, প্রবল feeling/state।": "～なければならない obligasyon; ～ずにはいられない hindi makontrol na udyok; ～てしょうがない hindi aksyon, kundi malakas na feeling/state.", "ভেতরের spring চেপে রেখেও লাফিয়ে বের হয়—না করে থাকা যায় না।": "Kahit pigilan ang spring sa loob, tumatalon itong palabas — hindi kayang hindi gawin.", "মজার video দেখে হাসি আটকাতে পারোনি—笑わずにはいられなかった বলো।": "Hindi mo napigilan ang pagtawa habang nanonood ng nakakatawang video — sabihin ang 笑わずにはいられなかった.", "Known reality/logic-এর ভিত্তিতে কোনো possibility সম্পূর্ণ বাতিল: “কোনোভাবেই এমন হতে পারে না।”": "Batay sa alam na realidad/lohika, ganap na tinatanggi ang isang posibilidad: “hinding-hindi ito maaaring mangyari.”", "Plain form＋わけがない; Nの／なAな＋わけがない। Strong, তাই মানুষকে উদ্দেশ করে বললে confrontational হতে পারে।": "Plain form＋わけがない; Nの／なAな＋わけがない. Malakas ito, kaya kung sasabihin tungkol sa tao, maaaring magtunog na confrontational.", "～はずがない logical expectation negative; ～わけがない আরও categorical; ～っこない casual ability/impossibility।": "～はずがない negatibo ng lohikal na inaasahan; ～わけがない mas kategorikal; ～っこない kaswal na kakayahan/imposibilidad.", "সম্ভাবনার দরজায় বড় X—তার ভেতরে ঢোকার “reason/わけ” নেই।": "Malaking X sa pinto ng posibilidad — walang “dahilan/わけ” para makapasok sa loob.", "সে প্রতিদিন পড়ে, তাই fail করার প্রশ্নই নেই—わけがない দিয়ে বলো।": "Araw-araw siyang nag-aaral, kaya walang tanong na babagsak siya — sabihin gamit ang わけがない.", "সব alternative বন্ধ; বাস্তবে বাকি একমাত্র option: “এ ছাড়া উপায় নেই।”": "Sarado ang lahat ng alternatibo; sa realidad iisa na lang ang natitirang opsyon: “wala nang ibang paraan kundi ito.”", "V辞書形＋しかない। বক্তা option-টি পছন্দ করতেই হবে এমন নয়; situation forced choice। Nしかない “শুধু N আছে” থেকে form আলাদা।": "V辞書形＋しかない. Hindi kailangang gustuhin ng nagsasalita ang opsyon; sapilitang pagpili dahil sa sitwasyon. Iba ang anyo sa Nしかない na “N lang ang mayroon.”", "রাস্তার সব দরজা বন্ধ, শুধু একটি খোলা—তার ওপর しかない।": "Sarado ang lahat ng pinto sa daan, iisa lang ang bukas — may しかない sa ibabaw nito.", "শেষ ট্রেন চলে গেছে, taxi নেওয়া ছাড়া উপায় নেই—しかない দিয়ে বলো।": "Umalis na ang huling tren, wala nang ibang paraan kundi sumakay ng taxi — sabihin gamit ang しかない.", "অনেক কারণের মধ্যে ঠিক A-ই গুরুত্বপূর্ণ/মূল কারণ—positive বা meaningful result-কে জোর দেয়: “ঠিক A বলেই।”": "Sa maraming dahilan, eksaktong A ang mahalaga/pangunahing dahilan — binibigyang-diin ang positibo o makabuluhang resulta: “dahil mismo sa A.”", "Plain form＋からこそ। সাধারণ negative excuse-এর চেয়ে মূল্যবান insight, effort, relationship-এ বেশি natural।": "Plain form＋からこそ. Mas natural sa mahalagang insight, pagsisikap, relasyon kaysa sa karaniwang negatibong palusot.", "～から শুধু কারণ; ～からこそ cause-এ spotlight; ～おかげで positive result-এর gratitude।": "～から dahilan lang; ～からこそ spotlight sa dahilan; ～おかげで pasasalamat sa positibong resulta.", "অনেক arrow-এর মধ্যে একটির ওপর spotlight—এই কারণこそ আসল।": "Spotlight sa isa sa maraming arrow — ang dahilan na ito こそ ang tunay.", "কঠোর পরিশ্রম করেছ বলেই সফল হয়েছ—からこそ দিয়ে বলো।": "Nagtagumpay ka dahil nagsikap ka nang husto — sabihin gamit ang からこそ.", "N-কে ছোট/তুচ্ছ করে বা নিজেকে বিনয়ের সঙ্গে নিচু করে: “N-এর মতো জিনিস/আমার মতো কেউ।”": "Pinapaliit/minamaliit ang N o ibinababa ang sarili nang may pagpapakumbaba: “isang bagay na tulad ng N / isang tulad ko.”", "Tone বিপজ্জনক। 私なんか humble হতে পারে; あなたなんか insulting। Positive encouragement-এ নিজের self-deprecation অতিরিক্ত কোরো না।": "Mapanganib ang Tone. Ang 私なんか ay maaaring humble; ang あなたなんか ay nakakainsulto. Huwag sobrahan ang self-deprecation sa sarili sa positibong paghihikayat.", "Rule 66-এ casual example “ইত্যাদি”; এখানে contempt/humility মূল। ～など formal এবং tone তুলনামূলক neutral।": "Sa Rule 66, kaswal na halimbawang “at iba pa”; dito pangunahing ang paghamak/pagpapakumbaba. Ang ～など ay pormal at medyo neutral ang tono kung ihahambing.", "N-কে হাতে ছোট করে দেখাচ্ছ—なんか। কার N ছোট করছ, সেটিই politeness ঠিক করে।": "Ipinapakita mong maliit ang N sa iyong kamay — なんか. Kung kaninong N ang pinapaliit mo, iyon ang nagpapasya sa pagiging magalang.", "“আমার মতো মানুষ কি পারবে?”—self-humble なんか দিয়ে বলো।": "“Ang tulad kong tao, kaya ko ba?” — sabihin gamit ang self-humble na なんか.", "কথ্য ভাষায় ability/possibility জোর দিয়ে অস্বীকার: “কোনোভাবেই করতে পারবে না/হবে না।”": "Sa sinasalitang wika, matinding itinatanggi ang kakayahan/posibilidad: “hinding-hindi niya ito magagawa/mangyayari.”", "Vます stem＋っこない। Casual, emotional; formal setting-এ わけがない／できるはずがない বেশি উপযুক্ত।": "Vます stem＋っこない. Kaswal, emosyonal; sa pormal na sitwasyon, mas angkop ang わけがない／できるはずがない.", "～わけがない general logical impossibility; ～っこない colloquial “অসম্ভব!” এবং action verb-এর stem।": "～わけがない pangkalahatang lohikal na imposible; ～っこない kolokyal na “imposible!” at stem ng action verb.", "ছোট っ দেয় শক্ত ধাক্কা—できっこない! মুখের জোর মনে রাখো।": "Ang maliit na っ ay nagbibigay ng malakas na tulak — できっこない! Tandaan ang lakas ng bibig.", "এত কাজ এক ঘণ্টায় শেষ করা অসম্ভব—終わりっこない দিয়ে বলো।": "Imposibleng tapusin ang ganito karaming trabaho sa isang oras — sabihin gamit ang 終わりっこない.", "A কারণটি সত্য হলেও শুধু সেটি থেকে extreme/simple conclusion B টানা যায় না: “A বলেই B—এমন নয়।”": "Kahit totoo ang dahilang A, hindi maaaring hilahin mula roon lang ang sukdulan/simpleng konklusyong B: “hindi ibig sabihin na dahil A, B na.”", "Aからといって、必ずしもBとは限らない／Bわけではない প্রায়ই জোড়া হয়। Stereotype/overgeneralization ঠেকায়।": "Aからといって、必ずしもBとは限らない／Bわけではない ay madalas magkapares. Pinipigilan nito ang Stereotype/overgeneralization.", "～ても বাধা সত্ত্বেও result; ～からといって cause থেকে ভুল conclusion অস্বীকার; ～とは限らない universality অস্বীকার।": "～ても resulta sa kabila ng balakid; ～からといって pagtanggi sa maling konklusyon mula sa dahilan; ～とは限らない pagtanggi sa pagiging unibersal.", "A থেকে B-তে arrow টেনেছিলে; মাঝখানে STOP sign—কারণ আছে, কিন্তু conclusion automatic নয়।": "Gumuhit ka ng arrow mula A papuntang B; may STOP sign sa gitna — may dahilan, pero hindi awtomatiko ang konklusyon.", "জাপানে থাকলেই জাপানি ভালো হয় না—からといって দিয়ে বলো।": "Hindi ibig sabihin na kung nakatira ka sa Japan, magaling ka na sa Japanese — sabihin gamit ang からといって.", "একটি statement অনেক ক্ষেত্রে সত্য হলেও সবসময়/সব মানুষের জন্য ১০০% নয়: “অবশ্যই এমন নয়।”": "Kahit totoo ang isang pahayag sa maraming kaso, hindi ito 100% palagi/para sa lahat: “hindi naman laging ganito.”", "Plain form＋とは限らない। Exceptions-এর দরজা খোলা রাখে; claim পুরো false বলছে না।": "Plain form＋とは限らない. Pinapanatiling bukas ang pinto para sa mga eksepsyon; hindi nito sinasabing ganap na mali ang claim.", "～わけではない statement আংশিক negate/explain; ～とは限らない universal certainty negate; ～かもしれない individual possibility।": "～わけではない bahagyang itinatanggi/ipinapaliwanag ang pahayag; ～とは限らない itinatanggi ang unibersal na katiyakan; ～かもしれない indibidwal na posibilidad.", "১০০% লেখা circle-এর এক ছোট অংশ মুছে দাও—limit universal নয়।": "Burahin ang maliit na bahagi ng bilog na may nakasulat na 100% — hindi unibersal ang limit.", "দামি জিনিস সবসময় ভালো নয়—とは限らない দিয়ে বলো।": "Hindi laging maganda ang mamahaling bagay — sabihin gamit ang とは限らない.", "কোনো অভিজ্ঞতার মাত্রা এত প্রবল যে বক্তা আবেগে বলে “N কী যে…!”—surprise, praise বা complaint।": "Napakalakas ng antas ng isang karanasan na emosyonal na sinasabi ng nagsasalita, “ano ba ang N na iyon…!” — gulat, papuri o reklamo.", "N（のこと）といったら। পরের clause-এ degree/evaluation আসে। Neutral topic introduction নয়; emotional exclamation।": "N（のこと）といったら. Sa sumunod na clause dumarating ang antas/pagsusuri. Hindi ito neutral na pagpapakilala ng paksa; emosyonal na pagbulalas.", "～というと association; ～といったら emotional degree; ～ほど degree-এর grammatical measure।": "～というと asosasyon; ～といったら emosyonal na antas; ～ほど gramatikal na sukatan ng antas.", "কথা বলতে গিয়ে হাত ছড়িয়ে “কী যে ছিল!”—এই dramatic gesture = といったら。": "Habang nagsasalita, iniunat ang mga kamay at nagsabing “ano ba iyon!” — ang dramatikong kilos na ito = といったら.", "গতকালের ব্যস্ততা কী যে ছিল—忙しさといったら দিয়ে বলো।": "Ano ba ang pagiging abala kahapon — sabihin gamit ang 忙しさといったら.", "A সত্য হওয়া সত্ত্বেও B আচরণ expectation-এর বিপরীত—এ নিয়ে রাগ, তিরস্কার বা contempt।": "Sa kabila ng pagiging totoo ng A, salungat sa inaasahan ang kilos na B — may galit, paninisi o paghamak tungkol dito.", "Plain＋くせに; Nの／なAな＋くせに। Subject সাধারণত একই/সংশ্লিষ্ট। নিজের ওপর self-criticism ছাড়া polite conversation-এ সতর্ক।": "Plain＋くせに; Nの／なAな＋くせに. Karaniwang pareho/magkaugnay ang Subject. Mag-ingat sa magalang na usapan maliban sa pagpuna sa sarili.", "“জানে, তবু…” বলে ভ্রু কুঁচকে থাকা মুখ—くせに-এর tone।": "Isang mukhang nakakunot ang noo na nagsasabing “alam niya, pero…” — ang tono ng くせに.", "জানার পরও সে বলেনি—知っていたくせに দিয়ে বলো।": "Kahit alam niya, hindi niya sinabi — sabihin gamit ang 知っていたくせに.", "কোনো গুণ surface-এ বেশি দেখা যায়, বা বারবার সেই tendency আছে: “-সুলভ/-ঘেঁষা/প্রবণ।”": "Ang isang katangian ay mas nakikita sa ibabaw, o paulit-ulit ang tendensyang iyon: “-ish/mahilig sa-/may hilig.”", "N＋っぽい, Vます stem＋っぽい, いA stem＋っぽい। Negative tendency common: 忘れっぽい, 油っぽい; তবে 大人っぽい neutral/positive হতে পারে।": "N＋っぽい, Vます stem＋っぽい, いA stem＋っぽい. Karaniwan ang negatibong tendensya: 忘れっぽい, 油っぽい; pero ang 大人っぽい ay maaaring neutral/positibo.", "～らしい true/expected characteristic; ～っぽい appearance/tendency, প্রায়ই imperfect; ～みたい direct resemblance।": "～らしい tunay/inaasahang katangian; ～っぽい anyo/tendensya, madalas hindi perpekto; ～みたい direktang pagkakahawig.", "আসল রং নয়, ওপরের দিকে সেই রঙের tint—っぽい।": "Hindi ang tunay na kulay, kundi tint ng kulay na iyon sa ibabaw — っぽい.", "তুমি সম্প্রতি একটু ভুলোমনা হয়ে গেছ—忘れっぽい দিয়ে বলো।": "Medyo naging makakalimutin ka kamakailan — sabihin gamit ang 忘れっぽい.", "A-কে খারাপ ফল B-এর দায়ী কারণ হিসেবে দেখায়: “A-এর দোষে।” Speaker blame/negative evaluation বহন করে।": "Ipinapakita ang A bilang dahilan na sisisihin para sa masamang resultang B: “kasalanan ng A.” May dalang sisi/negatibong pagsusuri ang nagsasalita.", "Plain/Nの＋せいで; uncertainty হলে せいか “হয়তো A-এর জন্য।” Neutral science/report-এ による বেশি।": "Plain/Nの＋せいで; kung hindi tiyak, せいか “baka dahil sa A.” Sa neutral na agham/ulat, mas madalas ang による.", "～おかげで ভালো ফল; ～せいで খারাপ ফল; ～ため neutral/formal cause।": "～おかげで magandang resulta; ～せいで masamang resulta; ～ため neutral/pormal na dahilan.", "কারণের গায়ে কালো “দোষ” sticker—せい。": "Itim na sticker na “sisi” sa dahilan — せい.", "ঘুম কম হওয়ার কারণে কাজে ভুল হয়েছে—せいで দিয়ে বলো।": "Dahil sa kakulangan ng tulog, nagkamali sa trabaho — sabihin gamit ang せいで.", "কোনো পরিচিত ব্যক্তির স্বভাব/ইতিহাস জানি বলেই তার ভবিষ্যৎ আচরণ সম্পর্কে prediction করি: “সে তো এমন মানুষ, তাই নিশ্চয়…”।": "Dahil alam ko ang ugali/kasaysayan ng isang kakilala, hinuhulaan ko ang kanyang kilos sa hinaharap: “siya ay ganoong tao, kaya siguradong…”", "Nのことだから। N সাধারণত speaker/listener-এর পরিচিত ব্যক্তি/group। Unknown object-এর objective cause নয়।": "Nのことだから. Ang N ay karaniwang tao/grupong kilala ng nagsasalita/tagapakinig. Hindi ito objective na dahilan ng isang hindi kilalang bagay.", "～から সাধারণ cause; ～のことだから character-based inference; ～に違いない conclusion-এর certainty, personality premise নয়।": "～から karaniwang dahilan; ～のことだから hinuha batay sa karakter; ～に違いない katiyakan ng konklusyon, hindi premise ng personalidad.", "ব্যক্তির profile card দেখে পরের action অনুমান—“ওর কথা যখন…” = のことだから।": "Tinitingnan ang profile card ng tao at hinuhulaan ang susunod na aksyon — “pagdating sa kanya…” = のことだから.", "সময়ের ব্যাপারে খুব সতর্ক বন্ধুটি নিশ্চয় দেরি করবে না—のことだから দিয়ে বলো।": "Ang kaibigang napakaingat sa oras ay siguradong hindi mahuhuli — sabihin gamit ang のことだから.", "সম্পূর্ণ অবস্থা নয়—সামান্য সেই দিকে ঝোঁক/লক্ষণ: “একটু… ভাব/প্রবণতা।” প্রায়ই শরীর বা negative condition।": "Hindi ganap na kalagayan — bahagyang hilig/senyales patungo sa direksyong iyon: “medyo… ang pakiramdam/tendensya.” Madalas katawan o negatibong kondisyon.", "N＋気味, Vます stem＋気味। 疲れ気味・遅れ気味। Temporary mild tendency; personality-এর দীর্ঘ habit-এ っぽい হতে পারে।": "N＋気味, Vます stem＋気味. 疲れ気味・遅れ気味. Pansamantalang banayad na tendensya; para sa matagal nang ugali ng personalidad, maaaring っぽい.", "～気味 mild/current sign; ～っぽい habitual/appearance; ～がち frequent negative tendency (এই page-এ না থাকলেও পার্থক্য মনে রাখো)।": "～気味 banayad/kasalukuyang senyales; ～っぽい nakagawian/anyo; ～がち madalas na negatibong tendensya (kahit wala sa page na ito, tandaan ang pagkakaiba).", "Dashboard needle danger zone-এ পুরো ঢোকেনি, একটু হেলে আছে—気味।": "Ang karayom sa Dashboard ay hindi pa ganap na pumapasok sa danger zone, medyo nakahilig lang — 気味.", "আজকাল একটু ঘুম কম হচ্ছে/ক্লান্ত লাগছে—気味 দিয়ে বলো।": "Kamakailan medyo kulang ang tulog mo/nakakaramdam ka ng pagod — sabihin gamit ang 気味.", "যে noun/action-কে reject করা হচ্ছে সেটিকে contempt/emotion সহ সামনে এনে শক্ত否定: “ওরকম N একদমই নয়/করব না।”": "Inilalagay sa harap nang may paghamak/damdamin ang noun/aksyon na tinatanggihan at matinding itinatanggi (否定): “hinding-hindi ang ganoong N / hindi ko gagawin.”", "Nなんか＋negative। Tone খুব শক্ত; জিনিস/নিজের idea-তে চলতে পারে, ব্যক্তির দিকে বললে অপমানজনক।": "Nなんか＋negative. Napakalakas ng Tone; maaaring gamitin sa bagay/sariling ideya, pero nakakainsulto kung sasabihin patungo sa tao.", "～なんか example বা humility হতে পারে; なんか…ない-এ negative predicate সঙ্গে strong rejection নিশ্চিত।": "Ang ～なんか ay maaaring halimbawa o pagpapakumbaba; sa なんか…ない, kasama ng negatibong predicate, tiyak ang matinding pagtanggi.", "N-কে হাত দিয়ে দূরে ঠেলে বলছ “না, একদম না!”—なんか…ない।": "Itinutulak mo palayo gamit ang kamay ang N at sinasabing “hindi, hinding-hindi!” — なんか…ない.", "“আমি মিথ্যা বলব না”—strong うそなんかつかない দিয়ে বলো।": "“Hindi ako magsisinungaling” — sabihin gamit ang matinding うそなんかつかない.", "সবচেয়ে extreme/minimum example-টিও সত্য বা মিথ্যা—সেখান থেকে অন্যগুলো আরও obvious: “এমনকি…ও।”": "Kahit ang pinakasudlan/pinakamababang halimbawa ay totoo o mali — mula roon mas halata ang iba: “maging ang… man.”", "Nさえ, particle＋さえ: 私にさえ。Context positive/negative দুটোই। Minimum condition-এর ～さえ～ば আলাদা extension।": "Nさえ, particle＋さえ: 私にさえ. Maaaring positibo/negatibo ang Context. Ang minimum na kondisyong ～さえ～ば ay hiwalay na extension.", "～も সাধারণ “ও”; ～さえ surprising extreme; ～まで unexpected endpoint/person পর্যন্ত।": "～も karaniwang “rin”; ～さえ nakakagulat na sukdulan; ～まで hanggang sa hindi inaasahang dulo/tao.", "সিঁড়ির একেবারে শেষ/অবিশ্বাস্য ধাপেও ✓—সেই extreme さえ।": "May ✓ kahit sa pinakahuli/hindi kapani-paniwalang hakbang ng hagdan — ang sukdulang さえ na iyon.", "এত ব্যস্ত যে দুপুরের খাবারের সময়ও নেই—時間さえない বলো।": "Napakaabala mo na wala ka nang oras kahit para sa tanghalian — sabihin ang 時間さえない.", "একটি example/result দিয়ে degree বোঝায়: “এতটা… যে/অন্তত এতটুকু।” কথ্য ভাষায় ぐらい খুব common।": "Nagpapahiwatig ng antas sa pamamagitan ng pagbibigay ng isang halimbawa/resulta: “sobrang… na / kahit ganito lang.” Napakakaraniwan ng ぐらい sa sinasalitang wika.", "Plain/N＋くらい／ぐらい। Extreme degree, minimum suggestion, approximation—context অনুযায়ী।": "Plain/N＋くらい／ぐらい. Sukdulang antas, mungkahing minimum, pagtatantya — ayon sa konteksto.", "～ほど degree তুলনায় একটু objective/strong scale; ～くらい কথ্য এবং “এই পরিমাণ”। くらいなら choice comparison-ও আলাদা।": "Ang ～ほど ay medyo mas objective/malakas na scale kumpara sa antas; ang ～くらい ay sinasalita at “ganitong dami.” Hiwalay din ang paghahambing ng pagpipilian sa くらいなら.", "হাতে একটি মাপ দেখিয়ে “এইটুকু/এতটা”—ぐらい।": "Ipinapakita gamit ang kamay ang isang sukat, “ganito kaliit/ganito kalaki” — ぐらい.", "এত ক্লান্ত যে নড়তে পারছ না—動けないくらい দিয়ে বলো।": "Napagod ka na hindi ka na makagalaw — sabihin gamit ang 動けないくらい.", "কাজ করে resulting state ঠিক না করে ফেলে রাখা, অথবা action একটানা চলতে থাকা: “যেমন আছে তেমন ছেড়ে/অবিরত।”": "Paggawa ng isang bagay at pag-iwan nito nang hindi inaayos ang resultang kalagayan, o patuloy na pagpapatuloy ng aksyon: “iwanan kung ano ito / walang tigil.”", "Vます stem＋っぱなし। 開けっぱなし neglect; 立ちっぱなし continuous. প্রায়ই negative burden/criticism।": "Vます stem＋っぱなし. 開けっぱなし pagpapabaya; 立ちっぱなし tuluy-tuloy. Madalas negatibong pasanin/kritisismo.", "～まま neutral unchanged state; ～っぱなし negligence বা long continuous effort জোর দেয়।": "～まま neutral na hindi nagbagong kalagayan; binibigyang-diin ng ～っぱなし ang pagpapabaya o mahabang tuluy-tuloy na pagsisikap.", "দরজা খুলে চলে গেছ—OPEN light সারাক্ষণ জ্বলছে: 開けっぱなし。": "Binuksan mo ang pinto at umalis — nakabukas ang OPEN light buong oras: 開けっぱなし.", "সারাদিন দাঁড়িয়ে কাজ করেছ—立ちっぱなし দিয়ে বলো।": "Buong araw kang nakatayong nagtrabaho — sabihin gamit ang 立ちっぱなし.", "একটি অনাকাঙ্ক্ষিত জিনিস অসংখ্য/সর্বত্র ছড়িয়ে “ভরা”: Nだらけ।": "Isang hindi kanais-nais na bagay na hindi mabilang/kumalat sa lahat ng lugar at “puno”: Nだらけ.", "泥だらけ・間違いだらけ・傷だらけ। সাধারণত negative/dirty/error; flowers দিয়ে neutral beauty বলতে いっぱい বেশি natural।": "泥だらけ・間違いだらけ・傷だらけ. Karaniwang negatibo/marumi/mali; para sabihin ang neutral na kagandahan gamit ang mga bulaklak, mas natural ang いっぱい.", "～まみれ-ও পুরো লেপা (বিশেষত liquid/dirt); ～だらけ countable/spread undesirable things-এর broad coverage।": "Ang ～まみれ rin ay ganap na nababalutan (lalo na liquid/dirt); ang ～だらけ ay malawak na saklaw ng mga bagay na hindi kanais-nais na nabibilang/kumakalat.", "সাদা জামার সব জায়গায় কাদার দাগ—泥だらけ।": "Mga mantsa ng putik sa lahat ng lugar ng puting damit — 泥だらけ.", "লেখাটি ভুলে ভরা—間違いだらけ দিয়ে বলো।": "Puno ng mga mali ang sinulat — sabihin gamit ang 間違いだらけ.", "কারও action/possibility সরাসরি assert না করে একটি possible example হিসেবে তুলে expression নরম করে।": "Hindi direktang iginigiit ang aksyon/posibilidad ng isang tao, kundi binabanggit ito bilang isang posibleng halimbawa para palambutin ang pahayag.", "Vたりして。Teasing, self-conscious confession, soft speculation। Rule 34 প্রশ্নস্বরের playful guess; এখানে statement-এ soft mention।": "Vたりして. Panunukso, nahihiyang pag-amin, malambot na haka-haka. Ang Rule 34 ay mapaglarong hula na may tono ng tanong; dito malambot na pagbanggit sa pahayag.", "～たり～たり multiple examples list; single ～たりして “এমনও করে/হয়তো এমন” softener।": "～たり～たり listahan ng maraming halimbawa; ang isahang ～たりして ay pampalambot na “gumagawa rin ng ganito / baka ganito.”", "কঠিন statement-কে bubble wrap দিয়ে জড়িয়ে বলছ—たりして।": "Binabalot mo ng bubble wrap ang isang matigas na pahayag habang sinasabi ito — たりして.", "ছুটির দিনে মাঝে মাঝে একাই সিনেমা দেখতে যাও—softly たりします বলো।": "Sa araw ng pahinga, paminsan-minsan pumupunta kang mag-isa para manood ng sine — sabihin nang malambot gamit ang たりします.", "N-এর সত্যিকারের expected বৈশিষ্ট্য যথাযথভাবে দেখা যায়: “N-সুলভ/একেবারে N-এর মতো হওয়া উচিত যেমন।”": "Ang tunay na inaasahang katangian ng N ay nakikita nang wasto: “tulad ng N / eksaktong kung ano ang dapat na maging N.”", "Nらしい／NらしいN। Person role, season, style: 春らしい日。Hearsay らしい-এর form একই, কিন্তু plain clause + source context-এ “শুনেছি”।": "Nらしい／NらしいN. Tungkulin ng tao, panahon, estilo: 春らしい日. Pareho ang anyo ng hearsay na らしい, pero sa plain clause + konteksto ng pinagmulan ay “narinig ko.”", "男らしい = culturally typical/manly; 男っぽい = surface masculine-ish; 男みたい = দেখতে/আচরণে লোকটির মতো।": "男らしい = tipikal ayon sa kultura/makalalaki; 男っぽい = panlabas na parang lalaki; 男みたい = tulad ng lalaking iyon sa itsura/kilos.", "Category checklist-এর সব box tick—তাই “সত্যিকারের Nらしい।”": "Naka-tick ang lahat ng box sa checklist ng Category — kaya “tunay na Nらしい.”", "আজ বসন্তের মতো উষ্ণ দিন—春らしい দিয়ে বলো।": "Ngayon ay isang mainit na araw na tulad ng tagsibol — sabihin gamit ang 春らしい.", "এক মুহূর্তে A মনে হয়েছিল, কিন্তু পরে বাস্তবতা আলাদা হলো—mistaken expectation/near misinterpretation।": "Sa isang sandali akala mo A, pero kalaunan iba pala ang realidad — maling inaasahan/muntik nang maling pagkaunawa.", "Plain＋かと思った。পরের clause-এ ら／が দিয়ে correction/contrast আসা natural। Literal “ভাবলাম কি না” নয়।": "Plain＋かと思った. Natural na dumarating ang pagwawasto/pagkakaiba gamit ang ら／が sa sumunod na clause. Hindi ito literal na “kung inisip ko ba.”", "～と思った শুধু past thought; ～かと思った “আমি তো ভেবেছিলাম/মনে হলো”—প্রায়ই surprise correction।": "～と思った past na inisip lang; ～かと思った “akala ko kasi / parang” — madalas pagwawasto na may gulat.", "চোখে প্রথমে এক ছবি, blink করার পর অন্য ছবি—প্রথম frame かと思った।": "Sa mata, unang isang larawan, pagkatapos kumurap ibang larawan — ang unang frame ay かと思った.", "ট্রেন এসেছে ভেবেছিলে, কিন্তু express চলে গেছে—かと思ったら দিয়ে বলো।": "Akala mo dumating na ang tren, pero dumaan lang ang express — sabihin gamit ang かと思ったら.", "পুরো list না দিয়ে কয়েকটি representative example casualভাবে পাশাপাশি রাখে: “যেমন A, B ইত্যাদি।”": "Hindi nagbibigay ng buong listahan, kundi naglalagay nang kaswal ng ilang halimbawang kinatawan nang magkatabi: “tulad ng A, B, atbp.”", "NとかNとか; V辞書＋とか। List অসম্পূর্ণ—আরও items আছে বোঝায়। Formal লেখায় ～や～など।": "NとかNとか; V辞書＋とか. Hindi kumpleto ang List — nagpapahiwatig na may iba pang items. Sa pormal na pagsulat, ～や～など.", "～たり～たり actions/examples এবং conjugation লাগে; ～とか～とか nouns/quoted options-এ casual; ～と সম্পূর্ণ list-এর অনুভূতি।": "Ang ～たり～たり ay mga aksyon/halimbawa at nangangailangan ng conjugation; ang ～とか～とか ay kaswal para sa nouns/mga opsyong sinipi; ang ～と ay may pakiramdam ng kumpletong listahan.", "Shopping list-এর শেষে “…” আছে—AとかBとか…。": "May “…” sa dulo ng Shopping list — AとかBとか….", "ছুটিতে রান্না বা সিনেমা দেখা ইত্যাদি করো—とか～とか দিয়ে বলো।": "Sa bakasyon, nagluluto ka o nanonood ng sine at iba pa — sabihin gamit ang とか～とか.", "প্রধান কাজ A করতে যাওয়ার/করার সুযোগে অতিরিক্ত ছোট কাজ B করা: “যেতে যেতেই/সুযোগে।”": "Habang papunta/gumagawa ng pangunahing gawaing A, gumagawa rin ng karagdagang maliit na gawaing B: “habang papunta na rin lang / sa pagkakataon.”", "Vる／Vた／Nの＋ついでに। A অবশ্যই মূল উদ্দেশ্য, B secondary ও সুবিধাজনক। শুধু একসঙ্গে দুই সমান কাজ নয়।": "Vる／Vた／Nの＋ついでに. Ang A ang dapat pangunahing layunin, ang B ay pangalawa at maginhawa. Hindi lang dalawang pantay na gawaing sabay.", "Main shopping bag-এর পাশে free ছোট bag—অতিরিক্ত কাজ B হলো ついで।": "Sa tabi ng Main shopping bag, isang libreng maliit na bag — ang karagdagang gawaing B ay ついで.", "স্টেশনে যাওয়ার পথে convenience store-এ ঢুকবে—ついでに দিয়ে বলো।": "Papunta sa istasyon, papasok ka sa convenience store sa daan — sabihin gamit ang ついでに.", "দেখা evidence/পরিস্থিতি থেকে বক্তা খুব শক্ত inference করে: “নিশ্চয়ই/নিঃসন্দেহে।”": "Mula sa nakikitang ebidensya/sitwasyon, gumagawa ang nagsasalita ng napakalakas na hinuha: “sigurado / walang duda.”", "Plain＋に違いない; N/なA-তে だ সাধারণত বাদ। Objective proof নয়, speaker certainty; formal/written-এ বেশি দেখা যায়।": "Plain＋に違いない; sa N/なA, karaniwang tinatanggal ang だ. Hindi objective na patunay, kundi katiyakan ng nagsasalita; mas madalas makita sa pormal/nakasulat.", "দুইটি clue মিলিয়ে detective বলছে “এটাই culprit—違いない!”": "Pinagsama ang dalawang clue at sinasabi ng detective, “ito ang culprit — 違いない!”", "আলো জ্বলছে, তাই কেউ নিশ্চয় ঘরে আছে—に違いない দিয়ে বলো।": "Nakabukas ang ilaw, kaya siguradong may tao sa bahay — sabihin gamit ang に違いない.", "একটি category-তে A-কে সর্বোচ্চ benchmark বানায়: “A-এর মতো এত… আর কিছু/কেউ নেই।” Negative form দিয়ে superlative।": "Ginagawang pinakamataas na benchmark ang A sa isang kategorya: “walang ibang bagay/tao na kasing… ng A.” Superlative gamit ang negatibong anyo.", "Aほど adjective Nはない／いない。 Speaker evaluation; absolute scientific ranking নাও হতে পারে।": "Aほど adjective Nはない／いない. Pagsusuri ng nagsasalita; maaaring hindi ito absolute na siyentipikong ranggo.", "Rule 44: BはAほど～ない = B কম; এখানে Aほど～はない = A-ই সবচেয়ে। B আছে কি না দেখে পার্থক্য ধরো।": "Rule 44: BはAほど～ない = mas kaunti ang B; dito Aほど～はない = ang A ang pinaka. Tingnan kung may B o wala para makuha ang pagkakaiba.", "Podium-এর ১ নম্বরে A; পাশে কেউ A-এর ほど উচ্চতায় নেই।": "Sa ika-1 lugar ng Podium ang A; walang sinuman sa tabi ang kasingtaas ng A sa ほど.", "স্বাস্থ্যের মতো গুরুত্বপূর্ণ কিছু নেই—ほど…ない দিয়ে বলো।": "Walang kasinghalaga ng kalusugan — sabihin gamit ang ほど…ない.", "N-কে পুরোপুরি বাদ দিয়ে কাজ/আলোচনা করা: “N ছাড়া/বাদ দিয়ে।” 抜く মানে টেনে বের করা।": "Gumagawa/nag-uusap habang ganap na inaalis ang N: “nang walang N / hindi kasama ang N.” Ang 抜く ay nangangahulugang hilahin palabas.", "N抜きでV, N抜きのN, N抜きにして। 冗談・朝食・本人-এর মতো যা সচরাচর থাকত সেটি intentionally omit।": "N抜きでV, N抜きのN, N抜きにして. Sinasadyang alisin ang karaniwang naroroon, tulad ng 冗談・朝食・本人.", "～なしで সাধারণ absence; ～抜きで deliberate exclusion এবং একটু formal/idiomatic। 人なしでも possible, 人抜きで meeting = তাকে বাদ দিয়ে।": "～なしで karaniwang kawalan; ～抜きで sinadyang pagbubukod at medyo pormal/idiomatiko. Posible ang 人なしでも, pero ang 人抜きで meeting = hindi siya kasama.", "Sandwich থেকে একটি ingredient টেনে “抜き” করে বের করো—N抜き。": "Hilahin palabas ang isang ingredient mula sa Sandwich at gawing “抜き” — N抜き.", "মজা বাদ দিয়ে সিরিয়াসভাবে কথা বলতে বলো—冗談抜きで।": "Sabihing mag-usap nang seryoso nang walang biro — 冗談抜きで.", "অনুভূতি, শারীরিক অবস্থা বা ইচ্ছা এত প্রবল যে নিয়ন্ত্রণ/উপেক্ষা করা যায় না: “ভীষণ…/সহ্য হয় না।”": "Napakalakas ng damdamin, pisikal na kalagayan o kagustuhan na hindi ito makontrol/mabalewala: “sobrang… / hindi matiis.”", "Vたくて／いAくて／なAで＋しょうがない・しかたがない। Intentional action নয়; uncontrollable feeling। Formalভাবে ～てなりません-ও আছে।": "Vたくて／いAくて／なAで＋しょうがない・しかたがない. Hindi sinadyang aksyon; hindi makontrol na damdamin. Sa pormal, mayroon ding ～てなりません.", "～ずにはいられない-এ feeling action করায়; ～てしょうがない-এ feeling/state নিজেই অসহনীয়। しかたがない প্রায় সমার্থক।": "Sa ～ずにはいられない, ang damdamin ang nagtutulak sa aksyon; sa ～てしょうがない, ang damdamin/kalagayan mismo ang hindi matiis. Halos magkasingkahulugan ang しかたがない.", "Feeling meter MAX-এ আটকে গেছে—“কিছু করার উপায় নেই” = しょうがない。": "Naka-stuck sa MAX ang Feeling meter — “walang magagawa” = しょうがない.", "পরিবারকে দেখতে খুব ইচ্ছে করছে—会いたくてしょうがない দিয়ে বলো।": "Gusto mo nang makita ang pamilya mo — sabihin gamit ang 会いたくてしょうがない.", "TRY! N3 — প্রতিটি Rule একবার বুঝে সারাজীবন মনে রাখো": "TRY! N3 — Unawain ang bawat Rule nang isang beses at tandaan habang-buhay", "১১৩টি Grammar • Rule-specific গভীর ব্যাখ্যা • সূক্ষ্ম ব্যবহার • confusing “VS” • মনে রাখার ছবি • ১,১৩০টি উদাহরণ": "113 Grammar • Malalim na paliwanag na partikular sa Rule • Pinong paggamit • nakakalitong “VS” • Larawan para matandaan • 1,130 halimbawa", "Rule-এর গভীর ব্যাখ্যা": "Malalim na paliwanag ng Rule", "একবার বুঝে সারাজীবন মনে রাখো": "Unawain nang isang beses at tandaan habang-buhay", "🧠 অর্থের মেরুদণ্ড": "🧠 Gulugod ng kahulugan", "🎯 সূক্ষ্ম ব্যবহার": "🎯 Pinong paggamit", "⚖️ সবচেয়ে বেশি গুলিয়ে যায়": "⚖️ Pinakamadalas malito", "🖼️ মনে রাখার ছবি": "🖼️ Larawan para matandaan", "← আগের Part": "← Nakaraang Part", "সব Part-এর তালিকা": "Listahan ng lahat ng Part", "পরের Part →": "Susunod na Part →", "Part 01 শুরু →": "Simulan ang Part 01 →", "N3 Grammar-এর সব ১১টি Part": "Lahat ng 11 Part ng N3 Grammar", "নিচের Part-গুলো ১ থেকে ১১ পর্যন্ত সম্পূর্ণ আছে। যেটি পড়বেন, সেটিতে tap করুন—শেষে আগের/পরের Part-এ যাওয়ার button-ও পাবেন।": "Kumpleto ang mga Part sa ibaba mula 1 hanggang 11. I-tap ang Part na babasahin mo — sa dulo makikita mo rin ang button para pumunta sa nakaraan/susunod na Part.", "সব ১১৩টি Grammar দেখুন": "Tingnan ang lahat ng 113 Grammar", "আগের বা পরের Grammar Part": "Nakaraan o susunod na Grammar Part"}, "frag": {}, "patterns": [{"s": "{n}টি Grammar • {done} শেখা", "t": "{n} Grammar • {done} natutunan"}, {"s": "Part {cur} / {total} • সব Part", "t": "Part {cur} / {total} • Lahat ng Part"}, {"s": "{n}টি Part • তালিকায় ফিরুন", "t": "{n} Part • Bumalik sa listahan"}, {"s": "{done} / {total} শেখা", "t": "{done} / {total} natutunan"}, {"s": "{done} শেখা • {left} বাকি", "t": "{done} natutunan • {left} natitira"}, {"s": "{n}টি Grammar পাওয়া গেছে", "t": "Natagpuan ang {n} Grammar"}]};
(function () {
  var D = window.AponarN3Deep;
  if (!D || !D.map) return;
  var map = D.map, frag = D.frag || {};
  function esc(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
  var pats = (D.patterns || []).slice().sort(function (a, b) { return b.s.length - a.s.length; }).map(function (p) {
    var names = [];
    var re = "^" + p.s.split(/(\{[A-Za-z]+\})/).map(function (seg) {
      var m = /^\{([A-Za-z]+)\}$/.exec(seg);
      if (m) { names.push(m[1]); return "([\\s\\S]*?)"; }
      return esc(seg);
    }).join("") + "$";
    return { re: new RegExp(re), names: names, t: p.t };
  });
  function fixValue(v) {
    if (typeof v !== "string" || !v) return v;
    if (Object.prototype.hasOwnProperty.call(map, v)) return map[v];
    if (Object.prototype.hasOwnProperty.call(frag, v)) return frag[v];
    for (var i = 0; i < pats.length; i++) {
      var m = pats[i].re.exec(v);
      if (m) {
        var caps = {};
        pats[i].names.forEach(function (n, j) { caps[n] = m[j + 1]; });
        return pats[i].t.replace(/\{([A-Za-z]+)\}/g, function (_, n) { return n in caps ? caps[n] : _; });
      }
    }
    return v;
  }
  var searchKeys = Object.keys(map).sort(function (a, b) { return b.length - a.length; });
  function fixRoot(root) {
    if (!root) return;
    var walker = document.createTreeWalker(root, 4, null);
    var texts = [], n;
    while ((n = walker.nextNode())) texts.push(n);
    for (var i = 0; i < texts.length; i++) {
      if (texts[i].parentNode && /^(SCRIPT|STYLE)$/.test(texts[i].parentNode.nodeName || "")) continue;
      var v = texts[i].nodeValue, nv = fixValue(v);
      if (nv !== v) texts[i].nodeValue = nv;
    }
    var els = root.querySelectorAll ? root.querySelectorAll("*") : [];
    for (var j = 0; j < els.length; j++) {
      var el = els[j];
      if (el.getAttribute) {
        var al = el.getAttribute("aria-label");
        if (al) { var na = fixValue(al); if (na !== al) el.setAttribute("aria-label", na); }
      }
      var ds = el.dataset && el.dataset.search;
      if (typeof ds === "string" && ds) {
        var out = ds;
        for (var q = 0; q < searchKeys.length; q++) {
          var k = searchKeys[q];
          if (out.indexOf(k) < 0) continue;
          var re = new RegExp("(?<![\\u0980-\\u09FF])" + esc(k) + "(?![\\u0980-\\u09FF])", "g");
          out = out.replace(re, function () { return map[k]; });
        }
        if (out !== ds) el.dataset.search = out;
      }
    }
  }
  var scheduled = false;
  function fixAll() { if (document.body) fixRoot(document.body); }
  function schedule() {
    if (scheduled) return;
    scheduled = true;
    setTimeout(function () { scheduled = false; fixAll(); }, 0);
  }
  function observe() {
    if (!window.MutationObserver || !document.body) return;
    new MutationObserver(schedule).observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ["aria-label", "data-search"] });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", function () { fixAll(); observe(); });
  else { fixAll(); observe(); }
  window.addEventListener("load", fixAll);
})();
